export default [{"id":220,"question":"ما رأي سماحتكم في إنتاج أفلام تحمل أفكارًا إسلاميةً تسدّ الفراغ الموجود والمُستغلّ حاليًا بأفلام خبيثة؟","title":"حكم عمل أفلام إسلامية بديلة عن الفاسدة","answer":"الجواب: والله هذا سُئلتُ عنه غير مرةٍ، والقول بجواز هذا قولٌ قويٌّ؛ حتى تمنع الأفلام الأخرى الخبيثة، أو يحصل بهذا التَّقليل والمُحاربة لها والمُقاومة لها.\nفالأفلام الإسلامية التي تعرض على الناس ما ينفعهم في دينهم وتُشجّعهم على الخير وتدعوهم إلى الحقِّ حتى تُحارب بها الأفلام الخبيثة؛ ما أعلم بها بأسًا؛ لما دعت الضَّرورةُ إليها؛ لأنَّ الناس في حاجةٍ الآن إلى أفلامٍ صالحةٍ تُحارب الأفلام الخبيثة التي بُلِي بها الناسُ.","link":"https://binbaz.org.sa/fatwas/4059/حكم-عمل-افلام-اسلامية-بديلة-عن-الفاسدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0227.mp3","categories":["مسائل فقهية متفرقة"]},{"id":409,"question":"نبتت في حوش بيتي أشجار طفيلية، وهي تُؤذي الأطفال، فهل يجوز أن أقطعها بعوضٍ أم بدون عوضٍ، في داخل الحرم؟","title":"حكم قطع الأشجار المؤذية في مكة","answer":"الجواب: هذه فيها شبهة، لكن الأقرب -والله أعلم- أنه يجوز قطعها؛ لإزالة الأذى، والعموم لا يُقطع شجرها ولا شوكها، حيث لم تكن في مثل هذا الأمر، أما إذا كانت تؤذي في الطريق، أو تؤذي الإنسان في بيته؛ فإنه يُزيلها، كما لو آذاه شيءٌ من المباحات كالقط له أن يقتله، إذا آذاه ولم يندفع شرُّه إلا بالقتل وهكذا، لكن إذا تيسر أن يجعل عليها شيئًا من التراب، يعني: بدون قطعٍ، يجعل عليها شيئًا من التراب الذي يُبقيها ويُزيل ضررها، إذا كان ذاك بالإمكان فهذا يكون حسنًا، أما الفدية فلا دليل عليها.","link":"https://binbaz.org.sa/fatwas/4824/حكم-قطع-الاشجار-الموذية-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0467.mp3","categories":["مسائل فقهية متفرقة"]},{"id":754,"question":"إنني ومجموعة من الزملاء قمنا برحلةٍ، وكلَّفوني بأن أكون أنا المسؤول الذي تُوضع عنده نفقة هذه الرحلة، وقد قمتُ بما يجب لهم -بجميع المُستلزمات- ولكن في الأخير بقي معي مبلغًا، وأبوا أن يأخذوه مني، فهل أنا أتصدق به أم هو لي أتصرف فيه؟","title":"حكم أخذ المال مقابل خدمة الزملاء في رحلة","answer":"الجواب: إذا سمحوا لك فهو لك والحمد لله، أنتم شيء واحد، ما داموا سمحوا لك في مقابل ما قمتَ به من الخدمة الطيبة والأمانة فلا بأس عليك أن تتصرف فيه، وأن تنتفع به؛ لأنهم قد سمحوا لك -إخوتك في الله- لا بأس، والحمد لله.","link":"https://binbaz.org.sa/fatwas/20637/حكم-اخذ-المال-مقابل-خدمة-الزملاء-في-رحلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0563فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1067,"question":"ما حكم قول الرجل: الله يلعن إبليس، أو سبَّه بحالٍ من الأحوال، خاصةً إذا كان يعتقد أنَّ لإبليس سلطةً عليه؟","title":"ما حكم سب أو لعن إبليس؟","answer":"الجواب:\nلا حرج في لعنه، ولكن التَّعوذ بالله أحسن، التَّعوذ بالله من الشيطان الرجيم أفضل، وإن لعنه فلا بأس، فقد لعنه النبيُّ ﷺ: جاء في الحديث الصحيح أنَّ الشيطان تفلَّتَ عليه وهو يُصلي، فقال له: ألعنُك بلعنة الله، فإذا لعنه فلا بأس، وإن استعاذ بالله من شرِّه فذلك أفضل، وكلاهما جائزٌ. والشيطان له سلطة على مَن اتَّبعه وتساهل معه، وأما المخلِصون لله والمؤمنون لا سلطانَ له عليهم: إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ [الحجر:42]، يقول جلَّ وعلا: إِنَّمَا سُلْطَانُهُ عَلَى الَّذِينَ يَتَوَلَّوْنَهُ وَالَّذِينَ هُمْ بِهِ مُشْرِكُونَ [النحل:100]، فالإنسان إذا اعتصم بالله وجاهد لله؛ يسلم من عدو الله، وإذا تساهل وغفل؛ سلّط عليه الشيطان، كما قال الله سبحانه: وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف:36]، فإذا غفل وتساهل؛ وسوس له عدو الله، وزيَّن له الباطل، وإذا اجتهد في ذكر الله وطاعة الله وحفظ جوارحه من معاصي الله؛ ابتعد عنه عدو الله: إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ.","link":"https://binbaz.org.sa/fatwas/21115/ما-حكم-سب-او-لعن-ابليس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0911ما حكم سب أو لعن أبليس؟ ابن باز فتاوى المحاضرات.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1079,"question":"مَن يُؤدي شعائر الإسلام من صلاةٍ وزكاةٍ، غير أنه لا يهتم بأمر المسلمين، هل هو آثمٌ؟","title":"هل يأثم من لا يهتم بأمر المسلمين؟","answer":"الجواب:\nنعم آثمٌ، الواجب عليه أن يهتم بأمر المسلمين، وأن يأمر بالمعروف، وينهى عن المنكر، ويُعَلِّم حسب طاقته، ويدعو إلى الله، ويُشارك في الخير، وقد رُوي عن النبي ﷺ أنه قال: مَن لم يهتم بأمر المسلمين فليس منهم، وإن كان في سنده ضعفٌ، لكن معناه صحيح من جهة العموم؛ لأنَّ الله أوجب على المسلمين فيما بينهم أن يتعاونوا على البر والتَّقوى، والذي ما يهتم ما تعاون معهم، وأوجب عليهم التواصي بالحقِّ، وهذا ما تعاون معهم، ولا تواصى، وأوجب عليه الأمر بالمعروف، والنَّهي عن المنكر، والدعوة إلى الله، وهذا مُهْمِلٌ مُعْرِضٌ، فيكون عليه وِزْرٌ من ذلك، ولكن الواجب عليه بقدر الطاقة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] مع أهله، ومع جيرانه، ومع غيرهم ممن يستطيع حسب طاقته، وحسب علمه، ولا يجوز الإهمال والإعراض، يرى المنكر ويسكت، ويرى أولاده على الباطل وأهله على الباطل ويسكت، لا، ما يجوز هذا، هذا غفلة وإعراض، ولا يُسمَّى: عدم اهتمام، بل إعراض وغفلة، وإقرار للمُنكر، وقسوة للقلب.","link":"https://binbaz.org.sa/fatwas/21137/هل-ياثم-من-لا-يهتم-بامر-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0933من يؤدي شعائر الإسلام من صلاة وزكاة غير أنه لا يهتم بأمر المسلمين هل هو آثم؟ ابن باز.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1106,"question":"أُفيدكم بأنني عندي إخوة صغار، ووالدتي ووالدي قد توفيا رحمهما الله، وخلف الوالدُ لهم أموالًا من بعد وفاته، مثل: الأغنام والجمال وغيرها، ومثل: الضمان الاجتماعي وأراضٍ وهكذا، وأنا أكبرهم وأعولهم وأصرف عليهم، بحيث إنني عسكري، وأستلم رواتب وأعولهم بها، هل يجوز لي أن أخلط حقِّي الخاص مع حقوقهم، وأتصرَّف بها؟ أفيدونا جزاكم الله خيرًا.","title":"حكم التصرف في مال الأيتام وخلطه بغيره","answer":"الجواب:\nنعم، لك أن تُنفق عليهم من أموالهم بقدر حاجتهم، تخلطها مع مالك، وما زاد على ذلك تجعله في شيءٍ ينفعهم، تجمعه وتشتري به عمارةً، أو دكانًا، أو أرضًا زراعيةً تنفعهم، إذا كان المال كثيرًا يمكن أن يُشترى به عمارة، أو فِلَّةً، أو دكانًا، أو مزرعةً تنفعهم، أو تُعطيه إنسانًا ثقةً يتَّجر فيه ويُنميه بالتِّجارة، وتأخذ منه قدر نفقتهم، تضمُّها إلى ما عندك وتُنفق عليهم، وإذا كنتَ محتاجًا تأخذ زيادةً بقدر حاجتك، مع نفقتهم، كما قال الله  في ولي اليتيم: وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ [النساء:6]، وما زاد على الحاجة مثلما تقدَّم تشتري به لهم فِلَّةً، أو عمارةً، أو أرضًا زراعيةً ينتفعون بها، تنفعهم وتبقى لهم، أو تُعطيه مَن يتَّجر فيه من أهل الخير والثِّقة والأمانة حتى ينمو.","link":"https://binbaz.org.sa/fatwas/21173/حكم-التصرف-في-مال-الايتام-وخلطه-بغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0969توفي والدي وخلَّف من بعدهم أموالاً هل يجوز لي أن أخلط حقي الخاص مع حق أخوتي وأتصرف بها؟.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1214,"question":"زوجي راتبه بسيط، وينتهي قبل نهاية الشهر، ولا يعمل أي عملٍ إضافيٍّ، وقبل أن يستلم الراتب الثاني –أي: في نصف الشهر، أو على آخره- يُحضر لنا اللحمَ والخضارَ والفاكهةَ، وأنا أشكُّ أنه من الحرام: في بيع المُخدرات، فماذا أفعل؟ هل آكل منه وأُطعم أطفالي؟ أم ماذا أفعل؟","title":"ما حكم من تشك أن زوجها يطعمهم من حرام؟","answer":"الجواب:\nعليك بالنَّصيحة له، تُذكرينه بالله: أن يتحرى الحلال، وما دام يقول: لا، ما هو بحرام، خلِّي عنك ظنَّ السُّوء، ظنُّ السوء اتركيه، قد يتسلَّف، قد يتدين ويشتري لكم، عليك بالظن الطيب، والله يقول جلَّ وعلا في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12]، ويقول النبيُّ ﷺ: إياكم والظنَّ، فإنَّ الظنَّ أكذبُ الحديث، عليك بالظنِّ الطيب، لا تظني به السُّوء، إلا إذا كنتِ تعلمين أنه اشترى هذا الطعام بالحرام: بالخمر، بالربا، لا، ما لم تعلمي احمليه على أحسن المحامل، وظني به الخير، وانصحيه، قد يكون استدان من الناس، قد يكون أعطاه بعض الناس مساعدةً.\nوعليه بالاقتصاد على قدر طاقته، وأنت كذلك لا تُكلِّفيه شيئًا يضرُّه، لا تُؤذيه، أنت اطلبي الشيء المستطاع، قولي له: لا تُكلِّف نفسك، أعطني المستطاع، ما هو بلزوم فاكهة، إذا عجز عن الفاكهة ما هو بلزوم الفاكهة، يأتي بالمستطاع، ولو ما تأكل إلا التمر، عاش النبيُّ والصحابةُ دهرًا طويلًا في المدينة ما يأكلون إلا التَّمر، ما عندهم غير التمر، اصبروا وصابروا، وأبشروا بالخير، لا تحضُّوه على ما يضرُّه من أكل الحرام، أنتِ لاحظي الكلام الطيب معه: يا فلان، يا أبا فلان، لا تُكلِّف، يكفي ما تيسر على قدر راتبك، مرة تمر، ومرة خبزة، ومرة لحمة، على ما تيسر، حتى يُسهّل الله الأمور.\nتقول عائشةُ رضي الله عنها: \"لقد هلَّ هلالٌ، ثم هلالٌ، ثم هلالٌ –يعني: في المدينة- ما أوقد في أبيات النبي محمد نار عليه الصلاة والسلام\"، قال لها ابنُ أختها: يا خالة، ما كان يعيشكم؟ قالت: \"الأسودان: التمر والماء\"، طعامهم التَّمر والماء، وربما خرج بعض الأحيان على بطنه الحجر، قد ربط على بطنه الحجر من الجوع، وهكذا جماعةٌ من الصحابة يخرجون -من المهاجرين- قد ربطوا الأحجارَ على بطونهم من الجوع.\nفعلى المرأة أن تُساعد زوجها بالكلام الطيب، والعمل الصالح، تُساعده ألا يتكلَّف: أعطنا، أعطنا، أعطنا، تحضه على البلاء، على قدر راتبه: يوم لحمة، ويوم ما في لحمة، ويوم فاكهة، ويوم ما في فاكهة، على قدر الحال.\nوهو كذلك يستقيم ويتَّقي الله، ويحذر المعاملات الخبيثة: من التدخين، أو المخدرات، أو الشيء الآخر من الأمور المحرَّمة، يحذر ويكتفي بالحلال، ويتَّقي الله، والله يجعل له العاقبة الحميدة: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].\nوعلى الزوجة -على كل زوجة- أن تُساعد زوجها في الحلال، ترفق به، تقول له الكلام الطيب: يا فلان، لا تتكلَّف، نحن راضون بما يسَّر الله، لا تكلف، لا تحض نفسك على الأذى، على قدر راتبك، تُعينه على الرضا بأمر الله، وعلى الاقتصاد، ما تقول: جيب وجيب وجيب لنا، وهات، وهات، وأنت تكذب وأنت، هذا غلطٌ، تحضونه على البلاء.","link":"https://binbaz.org.sa/fatwas/21270/ما-حكم-من-تشك-ان-زوجها-يطعمهم-من-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1124أمرأة تقول أشك أن زوجي يطعمنا من الحرام فماذا أفعل؟.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1526,"question":"ينتشر بين الناس الآن ما يُسمَّى بالحقوق، فإذا حصلت بين شخصين مغاضبةٌ فيقول أحدهما: إن كان الخطأ مني فعلي حقّ، وإن كان الخطأ منك فعليك حق، فيتحاكمان إلى شخصٍ ثالثٍ، فيقول: الخطأ على هذا، أو الخطأ على هذا، ثم يُقام الحقُّ على الشخص المُخطئ؟","title":"ما حكم الحقوق الشخصية بين الناس؟","answer":"الجواب:\nإذا اصطلحوا اصطلاحًا بدون إلزامٍ فلا بأس، أما الإلزام فلا يلزم إلا الشرع، أما إذا قال: يا فلان، إنا رضينا بك فأصلح بيننا، فلا بأس.","link":"https://binbaz.org.sa/fatwas/21626/ما-حكم-الحقوق-الشخصية-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحق الشخصي.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1615,"question":"رجل يقضي أوقاتًا في ركوب الخيل، هل هذا من العبادات؟","title":"هل يُعَدُّ ركوبُ الخيل من العبادة؟","answer":"الجواب:\nالمسابقة للتعلم ما فيها بأس: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الْخَيْلِ [الأنفال:60]، إذا كان قصده التعلم ليتمرن على الجهاد وقصده خير فلا بأس، أمَّا إذا كان قصده مزاحًا ولعبًا فهذا مباح من باب المباحات.","link":"https://binbaz.org.sa/fatwas/21719/هل-يعد-ركوب-الخيل-من-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ركوب الخيل من العبادة.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1644,"question":"بعض الناس دائمًا يُسافر في الصيف إلى الخارج لغرض التَّمشية، فهل هذا من إضاعة المال؟","title":"هل من إضاعة المال السفر للنزهة كل صيف؟","answer":"الجواب:\nلا، ما هو من إضاعة المال، إذا كان يأكل المال أو يتصدَّق به فما هو بإضاعةٍ، أما إذا كان يكنزه ويُبقيه فهذا من إضاعته، وهو عبثٌ لا يجوز، أما إذا كان يصيد ويأكل أو يُعطي الناس ويتصدَّق فما هو بإضاعته.\nس: وإذا كان للنُّزهة مثلًا؟\nج: ولو للنزهة، لكن لا يقتل الصيدَ عبثًا، كأن يقتله ويتركه، إذا قتله ليأكل أو ليبيع أو ليتصدّق فما هو بعبثٍ.","link":"https://binbaz.org.sa/fatwas/21749/هل-من-اضاعة-المال-السفر-للنزهة-كل-صيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من إضاعة المال السفر في الصيف باستمرار.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1713,"question":"ذكرتم في تعليقكم على كتاب \"فتح المجيد\" أنَّ النبي ﷺ استخدم الأموال التي كانت عند اللات في فداء عروة بن مسعود الثَّقفي.","title":"ما حكم الأموال التي في المشاهد الشركية؟","answer":"الجواب:\nفي قضاء دَين عروة بن مسعود.\nس: وورد في الحديث: أنَّ النبي ﷺ نهى عن حلوان الكاهن ومهر البغي، فكيف ..؟\nج: ما فيه تعارض، ما يوجد في المحلات المعبودة من دون الله يُصْرَف في مصالح المسلمين، كالذي يوجد عند اللات، فإذا كان هناك قبور تُعبد ولها خزائن، فأموالها تُصرف في مصالح المسلمين.","link":"https://binbaz.org.sa/fatwas/21819/ما-حكم-الاموال-التي-في-المشاهد-الشركية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف تصرف الأموال في المحلات المعبودة من دون الله.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1779,"question":"الضرب على الوجه: مُحَرَّمٌ مطلقًا؟","title":"ما حكم الضرب على الوجه؟","answer":"الجواب:\nضرب الوجه ما يجوز مطلقًا، إلا على سبيل القصاص.","link":"https://binbaz.org.sa/fatwas/21886/ما-حكم-الضرب-على-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الضرب على الوجه.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1789,"question":"القَيِّم على مال اليتامى إذا رأى المصلحة في عملٍ معينٍ هل يلزمه أن يستشيرهم ويبلغهم؟","title":"حكم تصرف القَيِّم في مال اليتامى للمصلحة","answer":"الجواب:\nلا، يفعل ما يراه من المصلحة: قُلْ إِصْلَاحٌ لَهُمْ خَيْرٌ [البقرة:220]، إذا رأى المصلحة ولم يكونوا أهلًا لأن يُستشاروا.","link":"https://binbaz.org.sa/fatwas/21896/حكم-تصرف-القيم-في-مال-اليتامى-للمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فعل المصلحة في مال اليتيم ومتى ينقطع اسم اليتيم.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1825,"question":"عندنا في أوروبا وفي أمريكا هناك أناسٌ يجرون عملية فيُغيِّرون الذكر إلى أنثى؟","title":"حكم عمليات تغيير الذكر إلى أنثى","answer":"الجواب:\nهذا يُسَمَّى الخنثى.\nس: كيف تكون التوبة عليهم؟\nج: ما يصير الذكر أنثى إلا إذا كان خُنْثَى، ففرج المرأة غير فرج الرجل.\nس: لكنهم يجرون عملية؟\nج: هذه عملية الخناثة.\nس: هل تنفع التوبة؟\nج: وإلا آلة رجل، وآلة أنثى، فإذا كان الغالب عليه صفات الأنثى أزالوا عنه علامات الرجل، وإذا كان الغالب عليه صفات الرجل أزالوا عنه علامات الأنثى.\nس: ما فيها بأس؟\nج: هذا يقع في الخناثة، فإذا وقع هذا فلا بأس به، لا بأس أن يُعامل معاملة الرجال إذا كانت الصفات الغالبة عليه صفات الرجل، ويعامل معاملة النساء إذا كان الغالب عليه صفات النساء.\nس: تُجْرَى العملية على مَن ليس له هذه الصفات، ليس بخنثى؟\nج: لا، هذا ما يُتصور، ما له فرج، فرج الرجل غير فرج المرأة.\nس: لكنهم يجرون العملية؟\nج: على كل حال، إذا كان بغير سببٍ فحرام ومنكر، وعندهم الشرك أكبر من هذا.","link":"https://binbaz.org.sa/fatwas/21933/حكم-عمليات-تغيير-الذكر-الى-انثى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عمليات تغيير الذكر إلى أنثى.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1838,"question":"ما العلاقة بالدم؟ فأحيانًا يكون دمُ الشخص مثلًا حارًّا فيطلع الشعر أبيض..؟","title":"هل لشيب الشعر علاقة بالدم؟","answer":"الجواب:\nلا، هذه لا بدَّ لها أسباب، لكن ما نعرف كل الأسباب، بعض الناس قد يأتيه الشيب مبكرًا، لكن أسبابه الله أعلم بتفصيلها، ففي الغالب إذا رُوِّع الإنسان ارتاع من شيء حدث عليه فجأةً فيرتاع؛ قد يَبْيَضّ شعره بسبب الروعة.","link":"https://binbaz.org.sa/fatwas/21947/هل-لشيب-الشعر-علاقة-بالدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لشيب الشعر علاقة بالدم.mp3","categories":["مسائل فقهية متفرقة"]},{"id":1975,"question":"هل هناك نهيٌ عن السباحة في البحر الميت؟","title":"هل يوجد نَهْيٌ عن السباحة في البحر الميت؟","answer":"الجواب:\nما أذكر شيئًا، لكن من جهة أنه آثار قوم غضب الله عليهم، مثلما قال ﷺ في قوم صالح: لا تدخلوا على هؤلاء المُعَذَّبين إلا أن تكونوا باكين، فهم قومٌ عُذِّبوا برمي الحجارة وقلب بلادهم عليهم، فينبغي ألا يُسْلَك بَحْرُهم، وألا يُسْبَح فيه، وأن يُبتعد عنهم بالكلية، فإذا مرَّ عليهم الإنسانُ يمر مسرعًا؛ لأنَّهم قومٌ عُذِّبوا في هذا المحل -نسأل الله العافية- وقال ﷺ في حقِّ قوم صالح: لا تدخلوا على هؤلاء المُعَذَّبين أن يُصيبَكم ما أصابهم.\nس: يُنهى عن السباحة فيه؟\nج: هو الأقرب، فالأظهر أنه لا ينبغي أن يُقرب، ولا يُسْبَح فيه؛ لأنه آثار قومٍ غضب الله عليهم وعُذِّبوا.","link":"https://binbaz.org.sa/fatwas/22091/هل-يوجد-نهي-عن-السباحة-في-البحر-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السباحة في البحر الميت.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2029,"question":"الانتساب إلى الجد؟","title":"حكم الانتساب إلى غير الأب","answer":"الجواب:\nما يجوز، ينتسب إلى أبيه، والجد جائز، لكن لا يترك الأب عمدًا، وإلا لو انتسب إليه؛ لأنه أشهر انتسابًا مثل قول النبي ﷺ: أنا النبي لا كذب، أنا ابن عبدالمطلب هو جده فإذا انتسب إليه لشهرته قال: أنا من ذريته، فهو صادق؛ هو من ذريته، لكن في الجنسيات وغير الجنسيات لا، يحط الأب؛ لأنه يكون له إخوة، يكون له أعمام؛ حتى يُعرف.\nس: هل يجوز أن ينتسب إلى عمه بحجة أنه هو الذي رباه؟\nالشيخ: لا ما ينتسب، ينتسب إلى أبيه بس، لا ينتسب إلى عمه ولا ابن عمه.\nس:... الآن بعض الصغار يقولون أبي مثلاً فلان وفلان، باسم أبيه وجده، يطلق على جده أباه.\nالشيخ: ما يخالف، لكن في الجنسية والإقامة والأشياء الرسمية لا بدّ يصحح الوضع إلى أبيه، أما الانتساب العام فلا بأس، مثل ما انتسب النبي ﷺ إلى عبدالمطلب أنا النبي لا كذب، أنا ابن عبد المطلب، ومثل ما يقال: العرب أولاد إسماعيل؛ نسبة إلى جدهم الأعلى، واليهود أولاد إسحاق جدهم الأعلى إسحاق؛ هذا لا بأس به، لكن الأمور الرسمية لا بدّ يثبت فيها الأب.\nس: ابن الأخت هل ينسب إلى أخواله؟\nالشيخ: ولكن لا ينسب إليهم في الرسميات، يقول أنا أخوالي آل فلان، أخوالي من مطير، أخوالي من بني هاشم، لكن لا ينتسب إليهم يقول: أنا ابن فلان الهاشمي ويكذب.\nس: أحسن الله إليك، مَن يستنكر اسم آبائه فينتسب إلى جده؛ لأن الاسم فيه غرابة؟\nالشيخ: ولو، لا بدّ في الجنسية والإقامة ونحوها يبين أباه، أما في العموم أنه من أولاد فلان الجد المشهور؛ لا بأس، هذا موجود في العرب ينتسبون إلى آبائهم المشهورين، لكن في الجنسيات التي عليها الأحكام الشرعية لا بدّ يكون إلى أبيه والجد أب.\nس: بعض الدول يسمون: حرم فلان، يعني باسم الزوج؟\nالشيخ: زوجة فلان حرم، هذا اصطلاح سهل، حرم فلان يعني زوجة فلان.\nس: لا، هي تنتمي إليه هو؟\nالشيخ: لاـ تنتمي إلى أبيها، هذا غلط، فلانة بنت فلان زوجة فلان ما يخالف.\nس: ما حكم تغيير اسم العوائل وليس القبائل، يغير اسم العائلة فقط\nالشيخ: إذا قال: من قريش أو من بني هاشم أو من مطير أو من... ما في بأس، لكن لا ينتسب إلى غير أبيه.","link":"https://binbaz.org.sa/fatwas/22145/حكم-الانتساب-الى-غير-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الانتساب إلى الجد أو العم أو الأخوال ونحوه.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2066,"question":"رجلٌ يسأل فيقول: إذا كان مشروعًا له أن يتكسَّب ليعِفَّ نفسه وأولاده، فهل يُشرع له أن يدَّخر من ماله لما بعد موته، يعني: يتكسَّب بنية أن يكتفي أولادُه من بعده؟","title":"حكم مَنْ يدخِّر من كَسْبه لأولاده بعد موته","answer":"الجواب:\nما فيه بأس، يدَّخر مثلما ادَّخر الصديقُ، وادَّخر عمر، وادَّخر عبدالرحمن بن عوف، لكن المقصود ألَّا يشتغل به عن الآخرة، فلا تصدُّه الأموال عن الآخرة، ولا تكون أكبر همِّه.","link":"https://binbaz.org.sa/fatwas/22184/حكم-من-يدخر-من-كسبه-لاولاده-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع الادخار من الكسب ليكفي أولاده من بعده.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2112,"question":"هل السِّمَن مذموم؟","title":"هل السِّمَن مذموم بكل حال؟","answer":"الجواب:\nإذا نشأ عن الغفلة والإعراض عن الآخرة، أمَّا إذا نشأ عن غير ذلك فلا يضرّه.","link":"https://binbaz.org.sa/fatwas/22230/هل-السمن-مذموم-بكل-حال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل السِّمَن مذموم.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2152,"question":"المسلم إذا سرق من كافرٍ ثم تاب وأراد أن يُرجِع إليه مالَه، ولا يستطيع لقاءَه، ماذا يفعل في المال؟","title":"حكم التصرف بمال الكافر إذا تعذّر تسليمه له","answer":"الجواب:\nيتصدَّق به عنه.\nس: طيب، وهل تنفع الصَّدقةُ الكافِرَ؟\nج: نعم، تنفعه في الدنيا.","link":"https://binbaz.org.sa/fatwas/22271/حكم-التصرف-بمال-الكافر-اذا-تعذر-تسليمه-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يسقط حق الكافر.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2336,"question":"مَن نقل البشارةَ لكن يشترط مثلًا أن يُعْطَى مبلغًا من المال أو هديةً ممن نقل إليه البشارة؟","title":"حكم التبشير بالمناسبات واشتراط مال لنقلها","answer":"الجواب:\nإن أعطاه هديةً يَقْبَل، وإن لم يُعطه فما هو بلزومٍ.\nس: التَّبشير بالمُناسبات السَّعيدة والنَّجاح؟\nج: نعم، نُهَنِّئك أو نُبَشِّرك بنجاح الولد، أو: بنجاح أخيك، أو: بنجاح ابنك، ما يُخالِف، طيب.","link":"https://binbaz.org.sa/fatwas/22460/حكم-التبشير-بالمناسبات-واشتراط-مال-لنقلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ينقل البشارة لكن يشترط أن يُعْطَى مبلغًا.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2410,"question":"يجوز دخول المكان اللي فيه تلفاز؟","title":"ما يفعل مَن دخل إلى مكان فيه تلفاز؟","answer":"الجواب:\nإذا ما شُغِّل ما في بأس.\nس: وإذا شُغِّل؟\nالشيخ: إذا شُغِّل ينبغي نصيحة صاحبه إلا إذا كان على شيء من قرآن، على علم، ما فيه صور نساء ولا فيه شيء منكر؛ أسهل للفائدة، لكن سد الباب أحوط، كون الإنسان يسد الباب أحوط؛ لأن الغالب التساهل.","link":"https://binbaz.org.sa/fatwas/22537/ما-يفعل-من-دخل-الى-مكان-فيه-تلفاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دخول الأماكن التي فيها تلفاز.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2620,"question":"بالنسبة لمسألة العبودية: أغلب المسلمين فهمهم أنَّ مَن كان لونه أسود يعتبر عبدًا؟ فماذا يكون هذا الفهم؟","title":"هل من لونه أسود يعتبر عبدًا؟","answer":"الجواب: هذا جهل، الناس قسمان: فيهم الأسود، والأبيض، والأحمر، من أولاد آدم.\nس: ولكن أغلب المسلمين هذا فهمهم؟!\nج: لا، فقط رأوا كثيرًا من العبيد سابقًا يكونون سُودًا فظنُّوا أنَّه هكذا.\nس: ألم يكن في عهد النبيِّ أناسٌ لونهم أبيض وكانوا عبيدًا؟\nج: بلى، زيد بن حارثة أبيض، وأسامة ولده أسود.\nس: ما الضابط من الناحية الشرعية في مسألة العبودية؟\nج: العبودية بالمِلك: مِلك الشراء، أو مِلك السَّبي.\nس: إن كان أبيض أو أسود؟\nج: سواء أسود أو أبيض، ولو أحسن من يوسف.\nس: حديث الرسول ﷺ: ولو تأمَّر عليكم عبدٌ حبشيٌّ هنا الرسول ﷺ ذكر أنَّ العبد حبشيٌّ على أنه أسود؟\nج: ما قال: أسود، عبدٌ حبشيٌّ، ولو ما هو بأسود، يعني: ولو تأمَّر عليكم أناسٌ عندكم أنَّهم مُحتَقَرون، اسمعوا وأطيعوا.","link":"https://binbaz.org.sa/fatwas/22755/هل-من-لونه-اسود-يعتبر-عبدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كل من كان لونه أسود يعد عبداً مملوكاً.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2775,"question":"السياحة المنهي عنها...؟","title":"ما السياحة الجائزة والمنهي عنها؟","answer":"الجواب: بخلاف المنصوص عليها. أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ [يوسف:109] لأخذ العبرة، لا للتَّفَكُّه.\nس: المنهي عنها التي يكون فيها إهانة للنفس وتعبد، وكذا الحديث هذا: لا سياحة في الإسلام؟\nالشيخ: سياحة أمتي الجهاد في سبيل الله السياحة اللي ما فيها نصر الدين ولا دعوة إلى الله، سياحة للنظر في الآثار، مثل ما قال ﷺ: لا تدخلوا على هؤلاء المعذّبين إلا أن تكونوا باكين يعني ما قصده الدعوة إلى الله وتعليم الناس وإرشاد الناس، إنما قصده المرور على الأرض ورؤية أهلها، هذه قال النبي ﷺ: لا تدخلوا عليهم إلا أن تكونوا باكين للاتعاظ والحذر مما أصابهم، لكن إذا سافر ما هو لأجل مجرد المرور على البلاد، للدعوة إلى الله، اقتداء بالصحابة واقتداء بما فعله الرسول ﷺ في إرسال الدعاة إلى البلاد وإلى الأمراء وإلى جهات الحاجة؛ لا بأس، للدعوة، للتعليم، للإرشاد والنصيحة.\nس: ما يُمَكَّن، إذا ذهب إلى بلد يريد أن يدعو إلى الله ما يُمَكَّن؟\nالشيخ: إذا كان ما يُمَكَّن لا يروح.\nس: بعضهم يقول: أنا للترفيه وتغيير الجو؟\nالشيخ: في بلاد المسلمين، يسافر إلى أبها، يسافر إلى مكة، يسافر إلى محل ما فيه خطر.","link":"https://binbaz.org.sa/fatwas/22923/ما-السياحة-الجاىزة-والمنهي-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السياحة المنهي عنها.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2787,"question":"بالنسبة للعِتْق في هذه الأيام يكاد يكون متعذرًا؟","title":"هل توجد رٍقاب يمكن عتقُها في هذا الزمان؟","answer":"الجواب: نادر إلا بالتوارث هذا شيء قليلأ لكن إذا قام الجهاد الحمد لله نسأل الله أن يقيم علم الجهاد.\nس: لكن موجود؟\nالشيخ: يوجد في موريتانيا ... بالتوارث.","link":"https://binbaz.org.sa/fatwas/22935/هل-توجد-رقاب-يمكن-عتقها-في-هذا-الزمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعذر العتق في هذا الزمان.mp3","categories":["مسائل فقهية متفرقة"]},{"id":2935,"question":"حكم التصفيق؟","title":"ما حكم التصفيق؟","answer":"الجواب: التصفيق من عمل الجاهلية، ما ينبغي، إذا دعت الحاجة إلى شيء: التكبير مثل ما في الصلاة أن النبي ﷺ قال: التصفيق للنساء، والتسبيح للرجال، والله يقول جل وعلا: وَمَا كَانَ صَلَاتُهُمْ عِنْدَ الْبَيْتِ إِلَّا مُكَاءً وَتَصْدِيَةً [الأنفال:35] قال العلماء: المكاء الصفير، والتصدية التصفيق، من أعمال الجاهلية.\nس: يكون مُحَرّمًا؟\nالشيخ: أقل أحواله الكراهة، والتحريم قريب وليس ببعيد، قوله: التصفيق للنساء يدل على أنه ليس من شأن الرجال، بل هو من شأن النساء أو الكفار.","link":"https://binbaz.org.sa/fatwas/23091/ما-حكم-التصفيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم التصفيق.mp3","categories":["مسائل فقهية متفرقة"]},{"id":3658,"question":"الكلام الحسن الجميل الذي يأخذ بالقلوب، بعض الناس يطلق عليه سحرًا؟","title":"هل يجوز وصف الكلام الحسن بالسحر؟","answer":"الجواب: يسمى سحرًا؛ هذا لأنه يسحر السامعين، مثل ما قال النبي ﷺ: إن من البيان لسحرًا.","link":"https://binbaz.org.sa/fatwas/23846/هل-يجوز-وصف-الكلام-الحسن-بالسحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يطلق على الكلام الحسن سحرًا.mp3","categories":["مسائل فقهية متفرقة"]},{"id":3683,"question":"بالنسبة نقل أحد عنكم العرضة الشعبية هذه التي تقام في المملكة، أحد له كتاب وذكر فيه أنكم وافقتموه على هذه؟","title":"حكم اللعب بالسيوف مع الطبل والدفوف","answer":"الجواب: إذا كان ما فيها منكر، اللعب بالسلاح مثل لعب الحبشة.\nس: لكن فيها دفوف وطبل؟\nالشيخ: الدفوف لا، بالسلاح بس، بالسيف والبندق، أما بالدفوف لا، ولا بالطبل؛ لكن مثل لعب الحبشة سواء.\nس: ولو مع الرقص؟\nالشيخ: الرقص ما له محل، هذا تقلُّب اللاعب ما يسمى رقصًا.\nس: ويجلسون الساعات الطوال، يعني يجلسون من بعد صلاة المغرب إلى ساعة متأخرة من الليل وهم يلعبون؟\nالشيخ: امنعهم إن كان لك قدرة امنعهم حتى يصلوا، أما أنت تبغي تمنع ما فعله النبي ﷺ وأقره، لا، ما أقره النبي ﷺ على العين والرأس، هو المشرع عليه الصلاة والسلام. أما ما زاد على ذلك يُمنع ،يقال: صلوا، يُمنعون من ترك الصلاة، يمنعون من اختلاط النساء بالرجال، يمنعون مما حرم الله.  أما إذا لعبوا باللعب الذي يعين على الجهاد ويكون عدة للجهاد؛ فلا بأس، بالسيف، بالرمح، بالحراب، مثل ما فعل الحبشة سواء.","link":"https://binbaz.org.sa/fatwas/23872/حكم-اللعب-بالسيوف-مع-الطبل-والدفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العرضة الشعبية.mp3","categories":["مسائل فقهية متفرقة"]},{"id":3694,"question":"أصحاب الجدّ؟","title":"ما معنى أصحاب الجَدّ؟","answer":"الجواب: الجَدّ يعني الغِنى.\nس: مِنْ أهل الجنة؟\nالشيخ: الأغنياء الذين هم من أهل الجنة يعني.","link":"https://binbaz.org.sa/fatwas/23883/ما-معنى-اصحاب-الجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصحاب الجَد.mp3","categories":["مسائل فقهية متفرقة"]},{"id":3781,"question":"الورثة يلزمهم رد الغلول؟","title":"هل يلزم الورثة رد الغلول؟","answer":"الجواب: يلزم ردّه، إذا عرفوا أنه غلول يلزم رده، الورثة.","link":"https://binbaz.org.sa/fatwas/23978/هل-يلزم-الورثة-رد-الغلول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الورثة يلزمهم رد الغلول.mp3","categories":["مسائل فقهية متفرقة"]},{"id":3796,"question":"الشجر الذي في الجبال ما تُملك لأحد؟ لا مانع أن الإنسان يرعى فيها؟","title":"حكم الرعي في الشجر الذي في الجبال","answer":"الجواب: هذا معروف بإجماع المسلمين: الناس شركاء في ثلاثة: الماء والكلأ والنار.","link":"https://binbaz.org.sa/fatwas/23995/حكم-الرعي-في-الشجر-الذي-في-الجبال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الناس شركاء في ثلاثة الماء والكلأ والنار.mp3","categories":["مسائل فقهية متفرقة"]},{"id":4069,"question":"كيف ياشيخ المسافر لا يؤجر؟","title":"هل يؤجر المسافر في سفره؟","answer":"الجواب: إذا كان سفرًا مباحًا، يعني: راح للبيع والشراء، على حسب نيته: إن كان قصده التَّعفف وطلب الحلال يُؤجر، مثلما قال النبيُّ ﷺ: الساعي على الأرملة والمسكين كالمجاهد في سبيل الله، أو قال: كالصائم لا يُفطر، والقائم لا يفتر، فيُشرع للمُسافر أن يأتي بأذكار السفر مطلقًا، ولو كان مباحًا، ولو كان معصيةً.","link":"https://binbaz.org.sa/fatwas/24308/هل-يوجر-المسافر-في-سفره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأجر في السفر.mp3","categories":["مسائل فقهية متفرقة"]},{"id":4394,"question":"إذا كان الإنسان أكبر أبنائه بنتًا هل يُكنى بها؟","title":"هل يكنى بالبنت إذا كانت أكبر الأولاد؟","answer":"الجواب: لا، يُكنى بالرجل أحسن، لأن الرجل ما يسأل عن بناته، يكنى بالرجال أبو شريح، والنبي ﷺ قال: أبو القاسم، وهو ليس من أكبر أولاده.\nس: إذا كان شاء الله أن هذا الشخص ما رزق بابن كلهم بنات ماذا يكون أمره؟\nج: ما هو بلازم الكنية، إذا أحب أن يتكنى بشيء، لكن لو كني بأبي فاطمة، أو بأبي عائشة، ما أعلم فيه بأسًا.","link":"https://binbaz.org.sa/fatwas/24671/هل-يكنى-بالبنت-اذا-كانت-اكبر-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكنى بالبنت إذا كانت أكبر الأولاد.mp3","categories":["مسائل فقهية متفرقة"]},{"id":4855,"question":"حكم إمضاء الشروط في العتق؟","title":"هل يجب إمضاء الشروط في العتق؟","answer":"يجب إمضاؤها، إذا قال: أنت حر لوجه الله إذا حفظت القرآن؛ فهو معلق، وإذا قال أنت حر لوجه الله إذا وصلت البلد، أنت حر لوجه الله إذا سلمت كذا وكذا؛ فالمسلمون على شروطهم.","link":"https://binbaz.org.sa/fatwas/25315/هل-يجب-امضاء-الشروط-في-العتق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجب إمضاء الشروط في العتق.mp3","categories":["مسائل فقهية متفرقة"]},{"id":4887,"question":"من أدرك ماله عند رجل وقد تغير تغيرًا كبيرًا؟","title":"حكم من أدرك ماله عند رجل وقد تغير كثيرًا","answer":"هو بالخيار، ما دام بعينه، مجرد أنه بس هَزُل يبغى يأخذه خير له، أما إذا كان ما هو بعينه، زاد، سمِن، من أول يسوي ألفين وصار يسوى ألفين وخمسين: ما يأخذه؛ لأنه زاد في ملك المشتري.\nس: من وجد ماله يأخذ بنفسه أو من طريق الدولة؟\nج: يأخذه عن طريق المحكمة، من طريق ولاة الأمور.","link":"https://binbaz.org.sa/fatwas/25399/حكم-من-ادرك-ماله-عند-رجل-وقد-تغير-كثيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أدرك ماله عند رجل وقد تغير تغيرًا كبيرًا.mp3","categories":["مسائل فقهية متفرقة"]},{"id":4978,"question":"هل يدخل الخدم في مسمى المملوك؟","title":"هل يدخل الخدم في مسمى المملوك؟","answer":"الجواب: لا، بس في المعنى، يلحقون به في المعنى، وإلا ما هم مملوكين، المملوك: العبد المملوك.","link":"https://binbaz.org.sa/fatwas/28291/هل-يدخل-الخدم-في-مسمى-المملوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل الخدم في مسمى المملوك؟.mp3","categories":["مسائل فقهية متفرقة"]},{"id":5042,"question":"متى ينقطع اسمُ اليتيم؟ هل هناك سِنٌّ معينٌ؟","title":"ما السِّنُّ التي ينقطع عندها اسم اليتيم؟","answer":"الجواب: إذا بلغ الحُلُم انقطع اليُتْم، إذا بلغ الحُلُم، خمسة عشر سنة، أو أنزل المَنِيّ، أو أنبت الشعر الخشن حول الفرج؛ ينقطع اسم اليتيم، مثلما في الحديث: لا يُتْم بعد احتلام.","link":"https://binbaz.org.sa/fatwas/29084/ما-السن-التي ينقطع-عندها-اسم-اليتيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما السِّنُّ التي ينقظع فيها اسم اليتيم؟.mp3","categories":["مسائل فقهية متفرقة"]},{"id":5068,"question":"بعض الناس يقول: يا صبر أيوب؟","title":"ما حكم قول \"يا صبر أيوب\"؟","answer":"الجواب: يقول: يا الله وفقني، ما هو يا صبر! الصبر ما يُدْعى. \nيقول: اللهم ارزقني الصبر الجميل، هذا طيب. أو يقول: اللهم ألهمني الصبر على طاعتك، والصبر عن محارمك، ولا يسأل البلاء، يقول: اللهم ارزقني الصبر على ما قضيت لي، والصبر على ما أمرتني، والصبر عما حرمت عليّ، يسأل ربه أنواع الصبر كلها؛ لأنه في حاجة إليها كلها.","link":"https://binbaz.org.sa/fatwas/29364/ما-حكم-قول-يا-صبر-ايوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم قول يا صبر أيوب؟.mp3","categories":["مسائل فقهية متفرقة"]},{"id":5074,"question":"استخدام الصَّافرة؟","title":"ما حكم استخدام الصَّافرة في الرياضة ونحوها؟","answer":"الجواب: ما ينبغي، ينبغي استعمال غير الصَّافرة، يستعمل شيء للدلالة على المراد غير الصَّافرة.\nس: لكنها ما تُتَّخذ تديُّنًا؛ لأنَّ صوتها قويٌّ، فليست صفيرًا بالأيدي إنما بالآلة؟\nالشيخ: يمكن، يمكن أن يستعملها؛ لأن المقصود البُعد عن التَّشبه بالجاهلية، فإذا اتَّخذ شيئًا مما يقوم مقامها كان في ذلك البُعد عن الجاهلية، أقل شيءٍ الكراهة.","link":"https://binbaz.org.sa/fatwas/29414/ما-حكم استخدام-الصافرة-في-الرياضة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم استخدام الصافرة في الرياضة ونحوها؟.mp3","categories":["مسائل فقهية متفرقة"]},{"id":5090,"question":"سائل يقول: فضيلة الشيخ/ عبد العزيز.السلام عليكم ورحمة الله وبركاته.أما بعد: إنني أحبك حبًا شديدًا، حبًا في الله لما قدمته لنا من الخير والفضل الذي تقدمه إلينا دائمًا في كل وقت.وبعد: كانت عائلتي صغيرة، وكنا نقطن في قرية صغيرة، وكان قد أصابنا جوع وقحط، وكانت أمي تأخذ من عند أهلها حَبًّا بدون علمهم ولا دراية منهم، فتطحنه وتقدمه لنا غذاءً. نريد من فضيلة الشيخ أن يفيدنا فيما يجب على الوالدة أن تفعله، وما هي الكفارة إذا كان علينا شيء؟ أفيدونا أثابكم الله!","title":"حكم من أخذت من بيت أهلها طعامًا لأطفالها","answer":"الجواب: أما حبك لأخيك في الله، فأقول: أحبك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم من المتحابين بجلاله، فقد قال عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي. ويقول ﷺ: سبعة يظلهم الله في ظله - وذَكَر منهم - المتحابين في الله. وأما ما يتعلق بما فعلته أمك في حال الجوع والحاجة مما تأخذ من بيت أهلها فلا حرج عليها في ذلك؛ لأن الواجب على أهلها من أبيها وأمها أن يطعموها وأن يطعموا أولادها إذا كان ليس لهم من يعينهم، ولا من ينفق عليهم، فالواجب عليهم أن ينفقوا ويحسنوا إليهم، والمسلمون شيء واحد، يجب عليهم أن يرحموا فقيرهم ويواسوه، ويحسنوا إليه، ويقوموا بحاجته، فالمسلم أخو المسلم. وفي الصحيحين عن ابن عمر رضي الله تعالى عنهما، قال: قال رسول الله ﷺ: المسلم أخو المسلم، لا يظلمه ولا يُسلمه -أي: لا يخذله، ويتركه لمن يظلمه- ومن كان في حاجة أخيه كان الله في حاجته. وقالت هند بنت عتبة: يا رسول الله! إن أبا سفيان رجل شحيح، لا يعطيني ما يكفيني ويكفي بَنِيَّ إلا ما أخذتُ من ماله بغير علم، فهل علي في هذا من جناح؟ فقال النبي ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك أي: بغير علم. فما أخذته أمك من أهلها من بيت أبيها وأمها، مما يسبب إنقاذها وإنقاذ أولادها، لا حرج فيه، ولا شيء عليها فيه ما دامت محتاجة، وليس هناك من يقوم بها غيرهم.","link":"https://binbaz.org.sa/fatwas/29993/حكم-من-اخذت-من-بيت-اهلها-طعاما-لاطفالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 009.mp3","categories":["مسائل فقهية متفرقة"]},{"id":5178,"question":"يقول: نسمع بعض الكلمات تتردد من بعض المسؤولين، يقول: إن العمل عمل، ولا دخل للدِّين في العمل؟","title":"ما حكم قول «لا دخل للدِّين في العمل»؟","answer":"الجواب: هذا كلامٌ باطلٌ، كيف ما له دخل في العمل؟! الدِّين هو كل شيءٍ، له دخلٌ في كل شيء: في أعمال الناس، وفي بيوتهم، وفي رئاستهم، وفي إمارتهم، وفي كل شيء، فالدِّين هو أصل كل شيءٍ، ويجب أن تكون الأعمال كلها على منهاج الدين، فيجب أن يُسْلِم العبدُ وجهَه لله في جميع الأمور: يَا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً [البقرة:208] يعني: في الإسلام جميعه، يجب الدخول في الإسلام جميعًا، وأن يتقيَّد بالإسلام في كل شيءٍ، ولا يجوز التَّملص في أي عملٍ، ولا في أي قولٍ، يجب أن تُوزن الأقوال والأعمال من الرؤساء والمرؤوسين، والرجال والنّساء، والجن والإنس؛ يجب أن تُوزن بميزان الشرع، فما وافقه أُخذ به، وما خالفه رُدَّ على قائله. والذي يقول: \"ما للدين دخلٌ بالأعمال\" يُستتاب، فإن تاب وإلا قُتل كافرًا -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/30113/ما-حكم-قول-لا-دخل-للدين-في-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 139.mp3","categories":["مسائل فقهية متفرقة"]},{"id":5560,"question":"لو كان الثلثان لا يفيان بما عليه من الدُّيون؟","title":"ما الحكم إذا لم يفِ الثلثان بديون الميت؟","answer":"الجواب: ولو، ينفذ الثلث، إلا مَن قال يُحجر عليه بمجرد كون ماله لا يُقابل ديونه، وأنَّ الحجر عليه يكون بنفس قلة المال، لا بحجر الإمام، وإلا فثلثه يكفي، ثلث ماله الذي عنده وقت النذر يكفي، والباقي يكون لحاجاته ودَينه وغير ذلك. س: ما اختاره شيخُ الإسلام أنَّ الإنسان إذا أوقف وعليه ديون أنَّ هذا الوقف لا ينفذ؟ ج: هذا مبني على الحجر، مبني على أنَّ الحجر يكون بنفس الإعسار، وإن لم يحجر عليه القاضي، وظاهر السنة وظاهر الأدلة الشرعية أنه لا حجرَ عليه إلا بعد حجر القاضي. س: لو قال: إنه يُسدد الديون التي عليه، ثم بعد ذلك ينظر في المال الباقي؟ ج: هذا معنى كلام المؤلف، كلام الإمام أحمد على هذا، لكن ظاهر السنة خلاف ذلك. س: لكن قال: يوم نذره، أخرج مقدار ثلث ماله يوم النذر؟ ج: هذا كلام أحمد، يُحكى عن أحمد بعد وفاء الدَّين. س: يكون الصواب يا شيخ: إخراج الثلث أولاً، ثم قضاء الدين؟ ج: يكون الثلثان لحاجاته ودَينه وكل شيء.\nس: يعني الذي يظهر لكم أنه يجب إخراج الثلث من جميع المال؟ ج: نعم حين النذر، ثم الباقي يكون في حاجاته وديونه. س: يعني ما يُقدِم وفاء الدين، ولو كان يستغرق ماله؟ ج: ما حجر عليه، لم يحجر عليه.\nس: قواعد الشَّريعة العامَّة في مسألة الديون وحقوق الناس أليست مُقدَّمةً؟ ج: ما يظهر لي، الرسول ما استفسره، ما قال: عليك دَين وإلا ما عليك دين؟ قال: يكفيك الثلث، ولم يستفسره، ترك الاستفسار مع الاحتمال ينزل منزلة العموم قال لكعبٍ: أمسك بعض مالك، فهو خيرٌ لك.\nس: لكن ما يُقال أنه كان يعلم حال كعب؟ ج: لا، حديث أبي لبابة أصرح منه، أصرح في الموضوع.[1]","link":"https://binbaz.org.sa/fatwas/31511/ما-الحكم-اذا-لم-يف-الثلثان-بديون-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 022.mp3","categories":["مسائل فقهية متفرقة"]},{"id":6348,"question":"هل الوساطة مثل الرشوة؛ علمًا بأن الوساطة بدون مال؟","title":"حكم الوساطة للغير","answer":"الجواب: إذا كانت الشفاعة، أو الوساطة تقتضي حرمان مستحق؛ لم يجز، أما إن كانت الوساطة، والشفاعة في توظيف، أو في قضاء دين، أو ما أشبه ذلك، ولا يعلم أنه يترتب عليها شيء من الضرر؛ فهذا لا بأس؛ لأن الرسول قال: اشفعوا تؤجروا واحد طالب حاجة، وشفعت له أن يعطى حاجته من قضاء دين، أو توظيف في محل مناسب؛ فلا بأس بهذا، إلا إذا علم أنه يترتب على توظيفه ظلم، بأن يقول: حطوه في مكان فلان، ووظفوه في مكان فلان من دون حق؛ لأنه قريب، أو صديق، لا يجوز هذا.","link":"https://binbaz.org.sa/fatwas/1926/حكم-الوساطة-للغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_711.mp3","categories":["مسائل متفرقة في العقيدة","مسائل فقهية متفرقة"]},{"id":6364,"question":"هل الوساطة مثل الرشوة؛ علمًا بأن الوساطة بدون مال؟","title":"حكم الوساطة للغير","answer":"الجواب: إذا كانت الشفاعة، أو الوساطة تقتضي حرمان مستحق؛ لم يجز، أما إن كانت الوساطة، والشفاعة في توظيف، أو في قضاء دين، أو ما أشبه ذلك، ولا يعلم أنه يترتب عليها شيء من الضرر؛ فهذا لا بأس؛ لأن الرسول قال: اشفعوا تؤجروا واحد طالب حاجة، وشفعت له أن يعطى حاجته من قضاء دين، أو توظيف في محل مناسب؛ فلا بأس بهذا، إلا إذا علم أنه يترتب على توظيفه ظلم، بأن يقول: حطوه في مكان فلان، ووظفوه في مكان فلان من دون حق؛ لأنه قريب، أو صديق، لا يجوز هذا.","link":"https://binbaz.org.sa/fatwas/1926/حكم-الوساطة-للغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_711.mp3","categories":["مسائل متفرقة في العقيدة","مسائل فقهية متفرقة"]},{"id":6901,"question":"في حوطة بعض المزارع، في حوطة بني تميم أصيبت الأرض بقلة الماء، وقد حفر أحد المزارعين في مزرعته ثلاثة ارتوازات، لكنه لم يوفق لوجود الماء، وقد ذكر له رجل يستطيع أن يحدد مكان وجود الماء بغرسه سيخ من الحديد في الأرض، فإذا سد السيخ استدل هذا الرجل على وجود الماء في هذه الأرض، ويقول: احفر هنا وستجد -إن شاء الله- الماء، وقد فعل صاحب المزرعة، فوجد ماء غزيرًا حلوا، وقد أشكل هذا على بعض أصحاب المزارع، وأرادوا أن يطلبوا من هذا الشخص أن يحدد لهم مكانًا في مزرعتهم ليصلوا إلى الماء؛ نظرًا لقلة عندهم، لكنهم توقفوا في هذا؛ خوفًا من أن يكون هذا الرجل يستعمل الشياطين، فنرجو الإجابة عن هذا السؤال، مع الملاحظة أن هذا الرجل مسن، ويبدو عليه الصلاح، أفيدونا مأجورين؟","title":"حكم تحديد وجود الماء بباطن الأرض بسيخ وغيره","answer":"الجواب: أولًا: اليوم هذا هو اليوم الرابع من.. نسأل الله أن يغيث العباد، وأن ينزل البركة على المسلمين، وأن يمن عليهم بغيث مبارك في قلوبهم، وفلاتهم .. الإيمان، والهدى، وبالغيث المبارك. ثانيًا: هناك علامات، ودلائل على وجود الماء، يعرفها أناس مختصون، ليس من باب الكهانة، ولا من باب استخدام الشياطين، ذكر ذلك أهل العلم، ومنهم ابن القيم -رحمه الله- ذكر دلائل كثيرة، يعرف بها وجود الماء في الأراضي من طريق الأهوية، ومن طريق الجبال، ومن طريق النبات، وطرق أخرى يعرفون بها وجود الماء في الصحراء، وفي القرى، وهم ناس يعرفون، وقد جربوا، ولكن ليسوا معصومين من الخطأ، قد يخطئون، قد يغلطون، ولكن في الغالب أنهم يصيبون، وقد يخطئون فيما يقررون. فإذا وجد من يستدل على الماء بعلامات يقول: إنه يعرفها، سواء بالسيخ، أو بغير السيخ، أو بأي شيء، وجرب ذلك، ولم يعرف عليه أنه يدعو الجن، أو يستغيث بالجن، أو يعمل أشياء منكرة؛ فلا مانع من الانتفاع به، والاستفادة منه، وهؤلاء موجودون من قديم، في هذه المملكة، وفي غيرها، وفي حائل أيضًا ناس معروفون بهذا الشيء. فالمقصود: أن هذا له ناس يعرفون هذه الأشياء، فإذا جربوا، ونجحوا في الغالب، ولا مانع من الاستفادة منهم، إلا إذا عرف أن واحدًا منهم، أو جماعة منهم يتعاطون أمورًا منكرة؛ فحينئذ يمنعون. السؤال:.. الجواب: على كل حال له أن يستدل بما يشاء، ما دام مباحًا شرعًا، بحافر يحفره، أو بسيخ يضربه، أو بصعود الجبال، ينظر الأهوية، وينظر النباتات، أو غير ذلك.","link":"https://binbaz.org.sa/fatwas/2830/حكم-تحديد-وجود-الماء-بباطن-الارض-بسيخ-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1278.mp3","categories":["مسائل متفرقة في العقيدة","مسائل فقهية متفرقة"]},{"id":7164,"question":"بقية السؤال المسرحيات، والتمثيليات؟","title":"حكم التمثيليات والمسرحيات","answer":"الجواب:\n\nأما التمثيل فالذي يظهر لنا أن التمثيل من باب الكذب، التمثيل أنه يمثل عمر، أو يمثل أبا جهل، أو يمثل فرعون، أو يمثل النبي ﷺ كلها فيما نعلم وفيما نفتي به أنها من الكذب، يكفي الآخرين ما كفى الأولين.\n\nإذا كان قصده النصح يقول: قال الله كذا، وقال الرسول كذا، وكان فلان يقول كذا، وكان عمر يقول كذا، كان الصديق يقول كذا، كان ابن تيمية يقول كذا، وأفتى بكذا، كان عمر بن عبدالعزيز يقول كذا.\n\nأما أنه يمثل نفسه، يقول: أنا عمر بن عبدالعزيز، أنا عمر بن الخطاب، أنا ابن تيمية، أنا ابن القيم، يجعل نفسه ابن القيم، ويتكلم على لسان ابن القيم، أو على لسان عمر بن عبدالعزيز، أو على لسان آخرين من أهل العلم، أو على لسان الصحابة، فهذا ليس بسديد، هذا كذب، وقد يقوله عنهم، ولا ينبغي أن يقال عنهم، وأن يمثلهم بما هم براء منه، وأما المسرحيات فلا نعلم تفصيلها، المسرحيات ما نعرف تفصيلها. \n\nالطالب: من قبل التمثيليات؟\n\nالجواب: نعم. \n\nالطالب: يعني مثل التمثيليات، يعني أشخاص يتقمصون أشخاصًا ..؟ \n\nالجواب: المسرحيات إن كانت تمثيليات، وإن كانت مجرد اجتماع على أشعار، أو على كلمات أدبية، أو على مقابلات بين شخص وآخر، هذا يقول كذا، وهذا يقول كذا، فلما يقولون حِكمهً، إن كان ما يقولون طيبًا؛ فهو طيب، وإن كان ما يقولون رديئًا؛ فهو ردئ، يعني المسرحيات كلمة إجمالية، مجملة لا نعرف ما تحتها. \n\nفإن كان المقصود من المسرحيات التمثيل، فالتمثيل مثل ما تقدم كذب، فإن كان المقصود من المسرحيات أنهم جماعة هذا يقول كلمة، وهذا يقول كلمة، وهذا يقول أبياتًا، وهذا يقول أبياتًا، أو هذا يدعو إلى كذا، وهذا يدعو إلى كذا، يتعاونون، فهذا له حكمه، إن كان ما يفعلونه فيما يرضي الله، وفيما أباح الله؛ فلا بأس، فإن كان فيما يسخط الله؛ فهي منكرة ومحرمة.","link":"https://binbaz.org.sa/fatwas/3199/حكم-التمثيليات-والمسرحيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1551.mp3","categories":["مسائل متفرقة في العقيدة","مسائل فقهية متفرقة"]},{"id":7778,"question":"أيضاً يقول، أو هذه رسالة من المرسل صلاح حامد اللهيبي يقول: سليمان الشبانة جزاكم الله خير، أرجو أن تعرض رسالتي على الشيخ: عبد العزيز بن باز ، يقول في رسالته هذه: كم يعدل الصاع بالمكاييل الحالية؟ وكم يعدل الفرسخ بالمقاييس الحالية أيضاً؟ وفقكم الله.","title":"مقدار الصاع والفرسخ حسب المقاييس العصرية","answer":"الجواب: أما الصاع في المقاييس الحالية فهو قريب من ثلاثة كيلو، الصاع النبوي قريب من ثلاثة كيلو إلا قليلاً، فإذا أخرج ثلاثة كيلو عن الصاع في الفطرة، زكاة الفطر فقد أخرج شيئاً كافياً.\nوأما الفرسخ: لا أعلم الآن مقداره بما يتعلق بالموازين الحالية، ما أتذكر الآن، ولكنه يعني لمن تأمله سهل؛ لأن البريد أربعة فراسخ، والبريد نصف يوم، فأربعة فراسخ تقريب اثنا عشر ساعة؛ لأن مسافة القصر عند جمع من أهل العلم أربعة برد، ستة عشر فرسخ، والبريد أربعة فراسخ نص يوم، يمكن يعادل بست ساعات، كل فرسخ ساعة ونصف تقريباً، فالحاصل أنه لمن تأمله يتضح له إن شاء الله، لأن الفرسخ معروف. نعم.\nالمقدم: يقول أيضاً: ما هو سجود السهو؟ ومتى يتعين؟ وكيف أداؤه؟ وهل هو قبل السلام أو بعده؟ وكيف أعمل إذا كنت لا أدري أنا سجدت سجدتين أو سجدة أو قرأت التحيات قبل الصلاة على النبي أو لا؟ وأغلب هذه الأحوال ظنون؟\nالشيخ: نعود إلى البحث الأول، يمكن أن يقدر الفرسخ تقريباً؛ لأن اليومين القاصدين أربعة برد، والبريد أربعة فراسخ، والأربعة ستة عشر فرسخ يوم وليلة، يعني أربع وعشرين ساعة، أربع وعشرين ساعة معناه أن البريد ست ساعات والفرسخ ساعة ونص، فيمكن أن يقارب البريد عشرين كيلو، ويكون الفرسخ قريب خمسة كيلو تقريباً؛ لأن أربعة فراسخ عشرين كيلو.. ستة عشر فرسخ ثمانين كيلو تقريباًً، وهذه مسافة القصر التقريبية عند الأكثر، ما يقاربها سبعين كيلو.. ثمانين كيلو مسافة قصر عند أكثرهم، يعني: إذا سافرها الإنسان قصر فيها الصلاة، هي وما يقاربها، وبهذا يعلم مقدار الفرسخ بالكيلو نعم، تقريب خمسة كيلو.","link":"https://binbaz.org.sa/fatwas/4985/مقدار-الصاع-والفرسخ-حسب-المقاييس-العصرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_047/04702.mp3","categories":["مسائل فقهية متفرقة"]},{"id":8229,"question":"أفتى أحد المشايخ لسائل عندما قال: إنه تاب ورجع إلى الله عز وجل، ولكن بماذا ترشدون من عنده أشرطة الفيلم الخليعة؟ فقال له الشيخ: كسرها وأرمها في البحر، و أليس من الأفضل من تكسيرها ورميها في البحر بأن يسجل فيها خطب وبرامج دينية؟ أفيدونا.","title":"كيفية التعامل مع الأشرطة الخبيثة","answer":"الجواب: نعم نعم، هذا هو الأولى؛ لأن فيها مالاً فلا يضاع، فيسجل عليها شيئاً طيباً وذلك يمحو ما فيها من الخبيث، والحمد لله.","link":"https://binbaz.org.sa/fatwas/6042/كيفية-التعامل-مع-الاشرطة-الخبيثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09703.mp3","categories":["مسائل فقهية متفرقة"]},{"id":9092,"question":"سؤال آخر: سمعت من بعض الناس أنه يقول: إذا فعلت عمل كالصلاة أو كالصوم أو أي عمل ثان في الدين أو الدنيا وسئلت: هل صليت؟ أو هل صمت أو عملت كذا وكذا؟ لا تقل: إن شاء الله. بل قل: نعم. لأنك عملته فعلاً، فما رأيكم في مثل هذا؟","title":"حكم قول إن شاء الله في الجواب عن أعمال العبادات","answer":"الجواب: هذا فيه تفصيل، أما في العبادات فلا مانع أن يقول: إن شاء الله، صليت إن شاء الله، صمت إن شاء الله؛ لأنه لا يدري هل كملها وقبلت منه أم لا؟ وكان المؤمنون يستثنون في إيمانهم وفي صومهم ونحو ذلك؛ نظرًا لأنه لا يدري هل كمل أم لم يكمل، فيقول: إن شاء الله، يعني: إن شاء الله أني صمت صومًا طيبًا سليمًا، ويقول: أنا مؤمن إن شاء الله. يعني: إيمانًا صحيحًا وإيمانًا أموت عليه.\nأما الشيء الذي لا يختلف قال: بعت هذا، فيقول: بعت إن شاء الله، ما يحتاج إن شاء الله، بعت هذا إن شاء الله، أو تغديت أو تعشيت إن شاء الله ما يحتاج إن شاء الله في هذا؛ لأن هذه أمور ما تحتاج إلى المشيئة في الخبر وإنما هي أمور عادية قد فعلها وانتهى منها، بخلاف أمور العبادات التي لا يدري هل وفاها حقها أم بخسها حقها، فإذا قال: إن شاء الله فهو للتبرك باسمه سبحانه وللتحرز من دعواه شيئاً قد يكون ما أكمله ولا أداه حقه. نعم.","link":"https://binbaz.org.sa/fatwas/7252/حكم-قول-ان-شاء-الله-في-الجواب-عن-اعمال-العبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15003.mp3","categories":["مسائل فقهية متفرقة"]},{"id":9235,"question":"وأولى رسائل هذه الحلقة وردت من شخص رمز لاسمه بـ (ع. أ. ع)، يقول في رسالته: نحن في مطلع العام الهجري الجديد، ويتبادل بعض الناس التهنئة بالعام الهجري الجديد قائلين: كل عام وأنتم بخير، فما حكم الشرع في هذه التهنئة بارك الله فيكم؟","title":"حكم التهنئة بالعام الهجري الجديد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فالتهنئة بالعام الجديد لا أعلم لها أصلاً عن السلف الصالح، ولا أعلم شيئاً من السنة أو من الكتاب العزيز يدل على شرعيتها، لكن من بدأك بذلك فلا بأس أن تقول: وأنت كذلك، إذا قال لك: كل عام وأنت بخير، أو قال: كل عام وأن تكون بخير، فلا مانع أن تقول له: وأنت كذلك، نسأل الله لنا ولك كل خير أو ما أشبه ذلك.\nأما البداءة فلا أعلم لها أصلاً. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7391/حكم-التهنىة-بالعام-الهجري-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23401.mp3","categories":["مسائل فقهية متفرقة"]},{"id":9432,"question":"سؤاله الأخير يقول: إنني لم أعزل من البيت إلى الآن، وإن معي أخي وأختي وأمي، وأعمل في إحدى البلاد العربية مدرسًا، وقضيتي أنني اشتريت قطعة أرض من فلوسي الخاصة، أي: من عرقي، وليس من البيت، فهل أكتب عقد الأرض بكل ما في البيت ولا أكتبها باسمي خاصة؟","title":"استحقاق الابن لأرضه التي اشتراها من ماله الخاص","answer":"الجواب: هذا فيه تفصيل: إذا كنتم شركاء فيما بينكم في الأرض بينك وبين أخيك وأخيك وأمك، وأما إن كنت مستقلًا بنفسك وإنما إذا حضرت جلست معهم في البيت فأنت مستقل فالأرض أرضك، وتكتب باسمك؛ لأنك اشتريتها من مالك، من حر مالك.\nأما إن كان هناك التباس في الأمر فيمكن حل المشكل من طريق المحكمة، أو من طريق المصلحين بينكم وبين أخيك وأختك وأمك، حتى ينظروا في الأمر بينكم ويصلحوا بينكم بعدما يسمعون كلام أخيك وكلام أختك وكلام أمك، ثم يكون الصلح بعد ذلك، أو في المحكمة وتحكم بينكم المحكمة.\nفالمقصود: أن الواجب عليك أن تأخذ رضا أمك وأختك وأخيك حتى لا يكون بينك وبينهم شحناء وعداوة وقطيعة، إما أن تصطلحوا بينكم، أو بواسطة من ترون من المصلحين والأخيار يصلحون بينكم، أو من طريق المحكمة إلا إذا سمح أخوك وأختك وأمك بأن تكون الأرض باسمك وليس لهم نزاع وليس لهم كلام في ذلك فالحمد لله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7597/استحقاق-الابن-لارضه-التي-اشتراها-من-ماله-الخاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/190015.mp3","categories":["مسائل فقهية متفرقة"]},{"id":9614,"question":"الرسالة التالية وصلت من المستمع الذي رمز إلى اسمه (و. ي. ع) من جمهورية مصر العربية، يقول في رسالته:هل الاستماع إلى المسلسلات والأفلام والغناء التي تذاع من محطات التلفزيون والإذاعات العربية والأجنبية حرام أم حلال أفيدونا أفادكم الله؟","title":"حكم المسلسلات والأفلام","answer":"الجواب: هذا فيه تفصيل: إذا كانت المسلسلات وما يذاع غيرها من أشرطة الفيديو أو غيره سليمة تصلح أمرًا ينفع الناس في الدين والدنيا كأن تذكر تاريخ غزوة من غزوات النبي ﷺ، أو تاريخ عمل إسلامي أو تراجم إسلامية أو تذكر شيئًا من المصانع النافعة للمسلمين أو ما أشبه ذلك فهذا لا بأس به.\nوهكذا الفيديو الذي يسجل شيئًا نافعًا للمسلمين من أحاديث دينية؛ قرآن.. أحاديث عن اختراعات نافعة.. أشعار جميلة طيبة عربية في الدين في الشجاعة في الإحسان إلى الفقراء.. في الجهاد في سبيل الله في غير هذا من وجوه الخير، هذا لا بأس به.\nأما إذا كانت مسلسلات ونحوها .... ونحو هذه بما يضر المسلمين في عرض الصور الخليعة والأغاني وأشباه ذلك فهذا لا يجوز؛ لأنه يضر المسلمين ..... انحراف أخلاقهم وربما أفسد عقائدهم فلا يجوز الاستماع لذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7772/حكم-المسلسلات-والافلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19311.mp3","categories":["مسائل فقهية متفرقة"]},{"id":9762,"question":"إحدى الأخوات المستمعات تقول: المرسلة: (غ. د. م) تقول: هناك شجرة نأخذ دائماً منها السواك، أراك أو غير الأراك، علماً بأن هذه الشجرة ليست لنا، وبدون علم صاحبها، فهل تدخل في حكم السرقة أو اللقطة، أم أن ذلك جائز أخذها؟ جزاكم الله خيراً.","title":"حكم الأخذ من شجرة ما بغير إذن صاحبها","answer":"الجواب: إذا كانت مملوكة في ملك إنسان مملوكة له فلا تأخذوا إلا بإذنه، أما إن كانت برية في البر فلا حرج الحمد لله، لكل أحد يأخذ منها، أما إن كانت في ملك إنسان فإنه يستأذن في أخذ بعض أجزائها سواكاً لا بأس إذا أذن، وإلا من دون إذن لا، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7936/حكم-الاخذ-من-شجرة-ما-بغير-اذن-صاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25710.mp3","categories":["مسائل فقهية متفرقة"]},{"id":9865,"question":"وله سؤال ثالث في نفس الرسالة يقول: ما حكم رمي الأشرطة المسجل عليها سور من القرآن الكريم أو أحاديث من أحاديث الرسول ﷺ، أو شيئاً من كلام العلماء رميها في الأماكن القذرة والمستنقعات؟","title":"حكم امتهان الأشرطة التي تحتوي على كلام الله","answer":"الجواب: لا يجوز رميها في الأماكن القذرة والمستنقعات؛ لأنها مشتملة على هذا الخير، فلا يجوز رميها، ثم هي مال لا يجوز أن يضاع، بل إذا كان لا يريد ما فيها في إمكانه أن يسجل عليها شيئاً آخر ينتفع به أو يعطيها بعض إخوانه ينتفع بذلك، أما إذا كان ما فيها إلا الشر، من الأغاني المحرمة، أو الشيء المحرم فلا بأس بطرحها وإتلافها. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8040/حكم-امتهان-الاشرطة-التي-تحتوي-على-كلام-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26308.mp3","categories":["مسائل فقهية متفرقة"]},{"id":10223,"question":"تقول: لدينا عادة؛ إذا بنى الإنسان منزلاً جديداً وأراد أن يسكنه لابد أن يذبح ذبيحة يسمونها: فتحة الدار، هل هذا الكلام صحيح؟ وهل له أصل؟","title":"حكم الذبيحة عند دخول المنزل الجديد","answer":"الجواب: إذا كان المقصود شكر الله جل وعلا على نعمته، فيدعو إخوانه وأحبابه وجيرانه، فلا بأس، أما إن كان عن اعتقاد، يذبح من أجل الجن، أو من أجل خوف الجن، هذا لا يجوز، وهذه عادة معروفة عند الناس إذا نزلوا بيتاً جديداً عمروه أو اشتروه، في الغالب يدعو إخوانه وأقاربه ويدعو جيرانه، يكرمهم شكراً لله على نعمة السكن، فإذا كان بهذه المثابة فلا شيء في ذلك، هذا من شكر الله، أما إن كان عن اعتقاد سيء، يذبحها من أجل الجن، أو خوف شر الجن، فلا يجوز. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8389/حكم-الذبيحة-عند-دخول-المنزل-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31006.mp3","categories":["مسائل فقهية متفرقة"]},{"id":10588,"question":"عندي أطفال صغار، وفي الليل أو حتى أثناء النهار يطلبون مني أن أروي لهم قصة، فأتخيل من عقلي قصة وأرويها لهم فهل، هذا يعتبر كذباً محرماً؟","title":"حكم حكاية الأم القصص الخيالية لأبنائها","answer":"","link":"https://binbaz.org.sa/fatwas/8768/حكم-حكاية-الام-القصص-الخيالية-لابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32506.mp3","categories":["مسائل فقهية متفرقة"]},{"id":11811,"question":"قرأت في أحد الكتب نصيحة، وهي ألا تجعل من عبادة الله عادة، كيف يجعل المسلم من عبادة الله عبادة لله، وليست عادة اعتادها؟ جزاكم الله خيرًا.","title":"معنى: (لا تجعل من عبادة الله عادة)","answer":"الجواب:  المعنى لا تصلها كعادة، صلها قربة، أن تتقرب بها إلى الله، ما هو من أجل العادة، إذا صليت الضحى صلها لأجل التقرب إلى الله، ما هو لأنها عادة، وهكذا إذا صليت التهجد بالليل؛ تصليها لأنها قربة؛ لأنها طاعة، ما هو لمجرد العادة، أو لأنه فعلها أبوك، أو أمك لا، تصلي تقربًا إلى الله، تصليها لأنها عبادة؛ لأنها طاعة لله، صلاة الضحى، صلاة الليل، النوافل مع الصلوات، هكذا، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9995/معنى-لا-تجعل-من-عبادة-الله-عادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42313.mp3","categories":["مسائل فقهية متفرقة"]},{"id":12419,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يقول: إنني سائق سيارة أجرة، ويأتيني بعض الركاب يطلبون توصيلهم إلى أماكن لم تؤثر زيارتها عن الرسول ﷺ قاصدين زيارتها، فما الحكم إذا حملتهم إلى تلك الأماكن، وأنا بقصدي المعيشة، وإذا لم أحملهم فسوف يتأثر مستوى معيشتي، وجهوني جزاكم الله خيرًا.","title":"حكم إيصال السائق الركاب إلى أماكن غير مشروع زيارتها","answer":"الجواب:  ليس لك أن تعين على البدع، فإذا كانت محلات غير مشروع زيارتها؛ فلا تحملهم إليها لا تطوعًا، ولا بأجرة، ولا تعن على الباطل والبدع، يقول الله سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]. فنقلك الناس إلى محلات لم يشرع الله زيارتها هذا لا يجوز لك، ولا يحل لك فعله، ولا أخذ الأجرة عليه جميعًا، ولكن تنصحهم، وتوجههم إلى الخير، وتقول: ما في حاجة للزيارة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10627/حكم-ايصال-الساىق-الركاب-الى-اماكن-غير-مشروع-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40215.mp3","categories":["مسائل فقهية متفرقة"]},{"id":12424,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يقول: إنني سائق سيارة أجرة، ويأتيني بعض الركاب يطلبون توصيلهم إلى أماكن لم تؤثر زيارتها عن الرسول ﷺ قاصدين زيارتها، فما الحكم إذا حملتهم إلى تلك الأماكن، وأنا بقصدي المعيشة، وإذا لم أحملهم فسوف يتأثر مستوى معيشتي، وجهوني جزاكم الله خيرًا.","title":"حكم إيصال السائق الركاب إلى أماكن غير مشروع زيارتها","answer":"الجواب:  ليس لك أن تعين على البدع، فإذا كانت محلات غير مشروع زيارتها؛ فلا تحملهم إليها لا تطوعًا، ولا بأجرة، ولا تعن على الباطل والبدع، يقول الله سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]. فنقلك الناس إلى محلات لم يشرع الله زيارتها هذا لا يجوز لك، ولا يحل لك فعله، ولا أخذ الأجرة عليه جميعًا، ولكن تنصحهم، وتوجههم إلى الخير، وتقول: ما في حاجة للزيارة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10627/حكم-ايصال-الساىق-الركاب-الى-اماكن-غير-مشروع-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40215.mp3","categories":["مسائل فقهية متفرقة"]},{"id":12717,"question":"هل سماع الراديو أثناء نزول المطر حرام، أم حلال؟","title":"حكم سماع الراديو أثناء نزول المطر","answer":"الجواب:  سماع الراديو لا يختلف في أي وقت في وقت المطر وغيره، إذا كان السماع لما أباح الله من القراءة والنصائح والأشياء التي لا حرج فيها يسمعها المؤمن في وقت المطر، وفي غيره. أما إذا كان السماع لما حرم الله من الأغاني الخليعة المنكرة، وأشباه ذلك مما حرم الله، وآلات اللهو هذا لا يجوز، لا في وقت المطر، ولا في غيره، لا يستمع الأغاني والملاهي والموسيقى والعود والرباب حتى في غير المطر، لا في الليل ولا في النهار، بل يتجنب هذه الأصوات الخبيثة، ولا يسمع إلا ما أباح الله من قراءة القرآن، أو الحديث الشريف، أو نصائح، أو ندوة علمية، أو أخبار يسمعها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10930/حكم-سماع-الراديو-اثناء-نزول-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46005.mp3","categories":["مسائل فقهية متفرقة"]},{"id":12733,"question":"لي زميل هرب من كفيلنا، وعندي عنوان زميلي الهارب، وكفيلي هددني بالترحيل إلى بلدي إذا لم أعرفه عنوان زميلي الهارب، فعرفته عنوان زميلي، فهل يعتبر هذا من باب الفتنة، وجهوني جزاكم الله خيرًا.","title":"حكم من أعان في الدلالة على هارب","answer":"الجواب:  إن كان الهارب مظلومًا؛ فلا تعرف به، وإن كان ظالمًا؛ فعرف به، وأعن على تحصيل الحق منه، وليس لك أن تكتم ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10947/حكم-من-اعان-في-الدلالة-على-هارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41806.mp3","categories":["مسائل فقهية متفرقة"]},{"id":12813,"question":"إحدى الأخوات المستمعات من المملكة الأردنية الهاشمية بعثت برسالة مطولة ملخص ما فيها: حكم سقي الأشجار المثمرة بمياه المجاري، هل هو جائز، أو لا؟","title":"حكم سقي الأشجار المثمرة بمياه المجاري","answer":"الجواب:  إذا كانت المياه نقية، وقد زال عنها أثر النجاسة، لا ريح فيها ولا طعم ولا لون؛ لا بأس، أما ما دامت خبيثة؛ فلا يسقى منها الشجر ولا الزرع، أما إذا كانت قد نظفت، وزال عنها الريح، ريح النجاسة، ولونها وطعمها؛ فلا حرج في ذلك، تشرب وتسقى بها الزرع، والنخيل أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11027/حكم-سقي-الاشجار-المثمرة-بمياه-المجاري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46301.mp3","categories":["مسائل فقهية متفرقة"]},{"id":13159,"question":"ننتقل بعد ذلك إلى سلطنة عمان السائلة (م. م) تقول في السؤال الأول: في بيتنا شجرة كبيرة ومثمرة، وهذه الشجرة تقف عائقًا في سبيل أن نبني محلات تجارية، وأسرتي ترغب في اقتلاعها، فما حكم الشرع في ذلك يا سماحة الشيخ؟","title":"حكم قطع الأشجار للمصلحة","answer":"الجواب:  لا حرج في ذلك، يعمل بالأصلح إذا كان قلعها أصلح، الحمد لله، ليس بإضاعة مال، هذا من مصلحة أهل الشجرة، فإذا رأوا أن قلعها أصلح؛ فلا بأس، النبي ﷺ لما كان في بناء مسجده في محل مسجده شجر؛ أمر بقلعه، أمر بقلع النخل لمصلحة توسعة المسجد.  فالمقصود: إذا كان في قلع الشجرة أو قطعها، سواء كانت نخلة أو رمانة أو تينة أو غير هذا من الشجر الذي ينفع، إذا اقتضت المصلحة قلعه؛ لبناء دور فيه، أو بناء مسجد، أو توسعة بيت، أو توسعة مسجد، كل ذلك لا حرج فيه، والحمد لله. المقدم: جزاكم الله خيرًا.. سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11414/حكم-قطع-الاشجار-للمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51018.mp3","categories":["مسائل فقهية متفرقة"]},{"id":13207,"question":"في بعض الأحيان تقول السائلة: أدخل مع بناتي الصغار خمس سنوات، وسبع سنوات الحمام، وذلك لمساعدتهن في تنظيف شعورهن، فهل إذا رأيت عورتهن هل علي شيء؟","title":"حكم رؤية عورة الطفل","answer":"الجواب:  لا حرج في ذلك مادام دون السبع فلا عورة لهم، الصبي والصبية تنظيفهم ومساعدتهم على النظافة؛ كل هذا لا بأس به، أما إذا بلغ سبعًا؛ فلا، يستر، تستر عورته، ولا تمس إلا للحاجة، تمسها أمه لأجل تنظيفه، أو تمسها الخادمة للتنظيف؛ فلا بأس، إذا كان ما ينظف نفسه، ما يعرف ينظف نفسه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11481/حكم-روية-عورة-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51211.mp3","categories":["مسائل فقهية متفرقة"]},{"id":13849,"question":"أختنا تقول: لنا أخت مريضة بعض الشيء وأحيانًا نضربها ضربًا خفيفًا لكننا نتألم نفسيًا، هل علينا في ذلك شيء؟","title":"هل ضرب المريض يترتب عليه إثم؟","answer":"الجواب: الواجب عليكم رحمة حالها وعدم فعل ما يزيد مرضها، وإذا كانت لا تتحمل الضرب ما يجوز لكم الضرب، أما إذا كان المرض خفيفًا وهي تخطي.. تعمل أشياء تستحق عليها التأديب الخفيف فلا بأس، لكن يجب أن تراعوا حالها إن كان الضرب يضرها فلا تضربوها ولا تزيدوها شرًا.\nأما إن كانت لا يضرها ذلك الضرب الذي تفعلونه معها؛ لأن مرضها خفيف والحاجة ماسة إلى تأديبها حتى ترتدع عما لا ينبغي فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/12223/هل-ضرب-المريض-يترتب-عليه-اثم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60217.mp3","categories":["مسائل فقهية متفرقة"]},{"id":15471,"question":"هذه أول رسالة في حلقتنا اليوم، وردت من المستمع: مسلم من قبرص، يقول: ما هو الواجب على المسلم تجاه غير المسلم، سواء كان ذميًا في بلاد المسلمين، أو كان في بلاده، والمسلم يسكن في بلاد ذلك الشخص غير المسلم، والواجب الذي أريد توضيحه هو المعاملات بكل أنواعها ابتداء من إلقاء السلام، وانتهاء بالاحتفال مع غير المسلم في أعياده، وهل يجوز اتخاذه صديق عمل فقط؟أفيدونا، أثابكم الله.","title":"واجب المسلم تجاه الكافر، وحكم السلام عليه ومشاركته في الاحتفالات","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن واجب المسلم بالنسبة إلى غير المسلم أمور متعددة، منها: الدعوة إلى الله ، وأن يدعوه إلى الله، ويبين له حقيقة الإسلام، حيث أمكنه ذلك، وحيث كانت لديه البصيرة؛ لأن هذا أعظم إحسان، وأكبر إحسان، يهديه إلى مواطنه، وإلى من اجتمع به من اليهود أو النصارى أو غيرهم من المشركين؛ لقول النبي ﷺ: من دل على خير فله مثل أجر فاعله وقوله -عليه الصلاة والسلام- لعلي  لما بعثه إلى خيبر، وأمره أن يدعوهم إلى الإسلام قال: فو الله لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم وقال -عليه الصلاة والسلام-: من دعا إلى هدى كان له من الأجر مثل أجور من تبعه، لا ينقص ذلك من أجورهم شيئًا فدعوته إلى الله، وتبليغه الإسلام، ونصيحته في ذلك، هذا من أهم المهمات، ومن أفضل القربات. ثانيًا: لا يظلمه، لا في نفس ولا في مال ولا في عرض، إذا كان ذميًا أو مستأمنًا أو معاهدًا، فإنه يؤدي إليه حقه، فلا يظلمه في ماله لا بالسرقة ولا بالخيانة، ولا بالغش، ولا يظلمه في بدنه بالضرب ولا بالقتل؛ لأن كونه معاهدًا أو ذميًا في البلد أو مستأمنًا هذا يعصمه. ثالثًا: لا مانع من معاملته في البيع والشراء والتأجير، ونحو ذلك، فقد صح عن رسول الله -عليه الصلاة والسلام- أنه اشترى من الكفار عباد الأوثان، واشترى من اليهود، وهذه معاملة، وقد توفي -عليه الصلاة والسلام- ودرعه مرهونة عند يهودي في طعام لأهله -عليه الصلاة والسلام-. رابعًا: في السلام لا يبدأه بالسلام، ولكن يرد؛ لقول النبي ﷺ: لا تبدؤوا اليهود ولا النصارى بالسلام وقال: إذا سلم عليكم أهل الكتاب، فقولوا: وعليكم فالمسلم لا يبدأ الكافر، ولكن متى بدئ، سلم عليك اليهودي أو النصراني وغيرهما، تقول: وعليكم، كما قاله النبي -عليه الصلاة والسلام-. هذا من الحقوق المتعلقة بين المسلم والكافر، ومن ذلك أيضًا حسن الجوار، إذا كان جارًا تحسن إليه، ولا تؤذيه في جواره، تتصدق عليه إن كان فقيرًا، تهدي إليه، تنصح له فيما ينفعه؛ لأن هذا مما يسبب رغبته في الإسلام، ودخوله في الإسلام؛ ولأن الجار له حق، قال النبي ﷺ: ما زال جبريل يوصيني بالجار، حتى ظننت أنه سيورثه وإذا كان الجار كافرًا كان له حق الجوار، وإذا كان قريبًا وهو كافر صار له حقان، حق الجوار، وحق القرابة.\nالمقدم: يأخذ من الصدقة العادية والزكاة؟\nالشيخ: من الحق الجائز أن يتصدق عليه إذا كان فقيرًا، يحسن إليه من غير الزكاة؛ لقول الله تعالى: لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ[الممتحنة:8] وفي الحديث الصحيح عن أسماء بنت أبي بكر -رضي الله تعالى عنهما- أن أمها وفدت عليها وهي مشركة في الصلح الذي بين النبي ﷺ وبين أهل مكة تريد المساعدة، فاستأذنت أسماء النبي ﷺ في ذلك هل تصلها؟ فقال النبي ﷺ: صليها نعم.\nالمقدم: بالنسبة لمشاركته في احتفالاته أو ...؟\nالشيخ: كذلك الاحتفالات ليس له المشاركة، المسلم لا يشاركهم في احتفالاتهم، في أعيادهم، لكن لا بأس أن يعزيهم في ميتهم إذا كان عندهم، عزاه في ميته، يقول: جبر الله مصيبتك، أو أحسن لك الخلف بخير، أو ما أشبهه من الكلام الطيب، ولا يقول: غفر الله له، ولا يقول: رحمه الله، إذا كان كافرًا.\nالمقدم: لا يدعو للميت. الشيخ: لا يدعو للميت، ولكن يدعو للحي بالهداية، بالعمل الصالح، ونحو ذلك، نعم. المقدم: نعم، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13996/واجب-المسلم-تجاه-الكافر-وحكم-السلام-عليه-ومشاركته-في-الاحتفالات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68801.mp3","categories":["مسائل فقهية متفرقة"]},{"id":15900,"question":"رسالة وصلت إلى البرنامج بتوقيع إحدى الأخوات المستمعات، تقول المرسلة أم المهند من جدة:فتاة عندها مال لزوجة أخيها، ولكنها أرجعت هذا المال، وبعد ذلك شكت في ذلك، وبعد حين وجدت مالًا في مكان فيه بعض حاجياتها الخاصة بها، فلم تعرف هل هذا المال خاص بوالدتها التي دائمًا تضع المال في أي مكان أم أنه خاص بزوجة أخيها؟ علمًا بأنها سألت زوجة أخيها فقالت لها: إنك أرجعتيه لي، وقالت مرة أخرى: وحتى لو كان معك فلا بأس، فنحن أختان، علمًا بأنها لا تعرف مقدار المال المؤتمن لديها من زوجة الأخ. سؤالي: هل تعطي المال لزوجة أخيها أم لوالدتها أم تتصدق به؟ علمًا بأن الوالدة قالت: يجوز أن يكون المال لي؟ أفتونا، جزاكم الله خيرًا.","title":"حكم من وجد مالاً في منزله ولا يعلم صاحبه","answer":"الجواب: هذا المال إذا كانت والدتها ترى أنه مالها، تعطيه والدتها، فإن كانت هي تظن أنه مالها، وأنها قد تضع في هذا المكان شيء من مالها، من مرتبها، من كسبها فهو مالها، الأصل أنه مالها، فإذا كان ليس لها مال بالكلية، وزوجة أخيها أخبرتها: أن حقها وصلها، فهذا يكون لأمها، ما دامت أمها تضع عندها بعض الشيء فهو لأمها، أما إذا كانت هي قد تضع مالًا لنفسها في هذا المكان فإنه مالها، الأصل أنه مالها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14497/حكم-من-وجد-مالا-في-منزله-ولا-يعلم-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74605.mp3","categories":["مسائل فقهية متفرقة"]},{"id":15944,"question":"يسأل سماحتكم عمن أخذ جهازًا من أجهزة الحكومة، واستفاد منه لمدة عشر سنوات، ثم عاد إلى رشده، هل يعيد ذلك الجهاز، أم يتبرع بقيمته، أم كيف يتصرف؟جزاكم الله خيرًا.","title":"كيفية التصرف لمن أخذ شيئًا من ممتلكات الحكومة","answer":"الجواب: إذا أمكن إعادته للحكومة بدون مضرة؛ أعاده وإلا فليتصدق به، أو بقيمته في فقراء المسلمين، والحمد لله، مع التوبة والاستغفار والندم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14549/كيفية-التصرف-لمن-اخذ-شيىا-من-ممتلكات-الحكومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71005.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16529,"question":"ماذا على من يسكن في حرم المدينة؟ وما هي حدوده بالتحديد، جزاكم الله خيرًا.","title":"ما يلزم من يسكن في حرم المدينة النبوية؟","answer":"الجواب: عليه أن يحذر ما حرم الله عليه في الحرم؛ من صيد... قطع الشجر، ونحو ذلك، كما أن عليه الحذر من المعاصي، والبدع كلها في الحرم، وفي غيره، لكن ما كان خاصًا بالحرم من الصيد، وغير ذلك؛ يحذره في حرم المدينة، وحرم مكة؛ لأن الرسول حذر من ذلك، عليه الصلاة والسلام. كما أن عليه أيضًا أن يحذر المعاصي كلها؛ لأنها في الحرم إثمها أكبر، في حرم المدينة، وحرم مكة، فالواجب أن يكون حذره منها أشد من حذره في بقية الأماكن، وأن يراقب الله في ذلك، وعلى سكان المدينة، وسكان مكة الحذر غاية من المعاصي؛ لأن إثم المعاصي في مكة، والمدينة أشد من إثمها في الطائف، أو في نجد، أو في الشام، أو في غير ذلك. الواجب على سكان الحرمين أن يتقوا الله غاية، وأن يحذروا ما حرم الله عليهم، وأن يحاسبوا أنفسهم؛ حتى لا يقعوا فيما حرم الله، فإن المعصية فيه عظيمة، وشديدة، وإثمها أكبر من فعلها في غير الحرمين، كما أن الحسنة تضاعف في الحرمين، لها مزية، وفي المسجدين لها مزية، فينبغي الإكثار من الطاعات في الحرمين، والاستكثار من الخير، والحذر كل الحذر من جميع المعاصي. المقدم: الله المستعان، جزاكم الله خيرًا، يسأل عن الحدود بالتحديد لو تكرمتم؟ الشيخ: الحدود موجودة في... إذا أراد يعرفها يسأل عنها ويقف عليها، نعم. المقدم: جزاكم الله خيرًا، إذًا هي بارزة وواضحة المعالم. الشيخ: موجودة، موجودة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/15267/ما-يلزم-من-يسكن-في-حرم-المدينة-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75707.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16592,"question":"من المستمع (م. س) رسالة يقول فيها: قبل حوالي خمس سنوات، وعمري آنذاك ستة عشر عامًا، أخذت من أخي مبلغًا من المال، ومقداره ألفان ومائتا ريال -تقريبًا- دون علم منه، وأنا الآن تبت إلى الله تعالى، والتزمت، فماذا يجب علي الآن يا سماحة الشيخ؟ علمًا بأن علي مبالغ من الديون، وأخي صاحب مال وغني.","title":"ما يلزم من أخذ مالاً من أخيه دون علمه؟","answer":"الجواب: عليك أن تخبره، وأن تطلب منه السماح، فإذا سمح؛ فالحمد لله، وإلا فعليك أن تؤدي إليه إذا استطعت، قال الله تعالى: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فعليك التوبة إلى الله، والندم، والعزم أن توفيه، وأن ترد عليه ماله، إلا إذا سمح، وأسقطه عنك؛ فجزاه الله خيرًا، والظن فيه أنه يسامحك مادام بخير، الحمد لله، الظن فيه أنه يسامحك، فاطلب منه السماح، وتب إلى الله من عملك، وأبشر بالخير، فإن أبى فعليك الوفاء بعد القدرة.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15334/ما-يلزم-من-اخذ-مالا-من-اخيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81714.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16603,"question":"من المستمع (م. س) رسالة يقول فيها: قبل حوالي خمس سنوات، وعمري آنذاك ستة عشر عامًا، أخذت من أخي مبلغًا من المال، ومقداره ألفان ومائتا ريال -تقريبًا- دون علم منه، وأنا الآن تبت إلى الله تعالى، والتزمت، فماذا يجب علي الآن يا سماحة الشيخ؟ علمًا بأن علي مبالغ من الديون، وأخي صاحب مال وغني.","title":"ما يلزم من أخذ مالاً من أخيه دون علمه؟","answer":"الجواب: عليك أن تخبره، وأن تطلب منه السماح، فإذا سمح؛ فالحمد لله، وإلا فعليك أن تؤدي إليه إذا استطعت، قال الله تعالى: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فعليك التوبة إلى الله، والندم، والعزم أن توفيه، وأن ترد عليه ماله، إلا إذا سمح، وأسقطه عنك؛ فجزاه الله خيرًا، والظن فيه أنه يسامحك مادام بخير، الحمد لله، الظن فيه أنه يسامحك، فاطلب منه السماح، وتب إلى الله من عملك، وأبشر بالخير، فإن أبى فعليك الوفاء بعد القدرة.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15334/ما-يلزم-من-اخذ-مالا-من-اخيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81714.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16623,"question":"من إحدى الأخوات المستمعات من جدة حي النزهة سؤال وهي الأخت (ع. ع. س) تقول: اعتدنا ألا نمد أرجلنا جهة القبلة منذ الصغر، والآن لما كبرنا أصبحنا نسأل عن الحكم الشرعي عن هذا الموضوع، فما هو توجيه سماحتكم؟ جزاكم الله خيرًا.","title":"حكم مد الأرجل إلى القبلة","answer":"الجواب: لا حرج في ذلك، لا بأس أن يمد الإنسان رجله إلى جهة القبلة، حتى ولو كان في المسجد الحرام إلى جهة الكعبة، لا حرج، قد جلس النبي ﷺ وأسند ظهره إلى الكعبة، عليه الصلاة والسلام. فالمقصود: أنه لا حرج كون الإنسان يمد رجله إلى جهة الكعبة، إلى جهة القبلة، لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15354/حكم-مد-الارجل-الى-القبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71607.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16840,"question":"من الأخت المستمعة (أ. س. أ) من مكة المكرمة رسالة وضمنتها جمعًا من الأسئلة: أول سؤال لها تقول فيه: هل يجوز أن أكتب أسماء الله باليد اليسرى؛ لأني لا أعرف أن أكتب إلا باليد اليسرى؟","title":"حكم كتابة الأسماء الحسنى باليد اليسرى","answer":"الجواب: لا حرج في ذلك؛ لأنك معذورة، أما السليم فالسنة أن يكتب باليمنى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15613/حكم-كتابة-الاسماء-الحسنى-باليد-اليسرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82410.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16870,"question":"ألاحظ بعض أسماء الله  على بعض الأشياء التي مصيرها إلى النفايات، والزبالة، فمثلًا البضاعة الفلانية من وارد عبدالله مثلًا، أو من وارد عبدالعزيز، وهذه الأشياء ترمى بعد الانتهاء من قضاء الحاجة منها، ترمى في مكان النفايات، فما هو توجيهكم للناس؟ جزاكم الله خيرًا.","title":"حكم رمي الأوراق التي عليها اسم الله في النفايات","answer":"الجواب: الإثم على من رماها في النفايات، والقمامات، كل شيء فيه ذكر الله من قصاصات الجرائد، أو الرسائل، أو إعلانات، أو غير ذلك، يجب أن يكرم، ويصان، أو يدفن في أرض طيبة، أو يحرق، أو يسحق بمكائن التي تسحقه حتى لا يبقى له أثر.  أما أن يلقى في النفايات، والمزابل هذا لا يجوز، والإثم على من ألقاه، لا على من كتبه، الإثم على من ألقاه؛ لأن الناس يضطرون إلى أن يكتبوا في رسائلهم، وفي بضائعهم التي ينوهون عنها، ويعلنون عنها أنهم مضطرون إلى اسم عبدالله، أو عبدالعزيز، أو في الرسائل إلى التسمية، وغير ذلك، وهكذا في الصحف يكون فيها مقالات، ويكون فيها آيات. فالحاصل: أن كل ما فيه ذكر الله؛ يجب أن يصان، إما بإتلافه بطريقة تتلفه بالكلية، وتسحقه لا يبقى له أثر، أو بدفنه في أرض طيبة، أو بتحريقه، أو بحفظه في مكان طيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15628/حكم-رمي-الاوراق-التي-عليها-اسم-الله-في-النفايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82421.mp3","categories":["مسائل فقهية متفرقة","مسائل متفرقة في العقيدة"]},{"id":16981,"question":"تقول: أبي يعمل بالتجارة، إلا أنه يبيع السجائر، وحسب الفتاوى التي قرأتها فإن ذلك يعد محرمًا، فهل يصح أن آخذ من ماله، مع العلم أنني فتاة، وأعيش معه؟","title":"حكم الأخذ من المال المختلط","answer":"الجواب: لا حرج في ذلك؛ لأن المال المختلط لا بأس بالأخذ منه، وقبول الهدية منه، ولو أقل أن يسلم مال من نقص، وخلل. ولكن ينصح من قبلك، ومن قبل إخوانك، أو أعمامك، أو غيركم من الناس الطيبين، ينصح حتى يدع بيع الدخان؛ لأن بيع الدخان منكر لا يجوز، لكن لا يضرك؛ لأن ماله مختلط، فلا يضرك الأكل من ماله، أو اللبس إلى غير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15794/حكم-الاخذ-من-المال-المختلط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82915.mp3","categories":["مسائل فقهية متفرقة"]},{"id":16998,"question":"تقول: أبي يعمل بالتجارة، إلا أنه يبيع السجائر، وحسب الفتاوى التي قرأتها فإن ذلك يعد محرمًا، فهل يصح أن آخذ من ماله، مع العلم أنني فتاة، وأعيش معه؟","title":"حكم الأخذ من المال المختلط","answer":"الجواب: لا حرج في ذلك؛ لأن المال المختلط لا بأس بالأخذ منه، وقبول الهدية منه، ولو أقل أن يسلم مال من نقص، وخلل. ولكن ينصح من قبلك، ومن قبل إخوانك، أو أعمامك، أو غيركم من الناس الطيبين، ينصح حتى يدع بيع الدخان؛ لأن بيع الدخان منكر لا يجوز، لكن لا يضرك؛ لأن ماله مختلط، فلا يضرك الأكل من ماله، أو اللبس إلى غير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15794/حكم-الاخذ-من-المال-المختلط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82915.mp3","categories":["مسائل فقهية متفرقة"]},{"id":17050,"question":"تقول السائلة: لقد ظلمني عدد من الناس، وحينما يبلغ بي الألم النفسي مبلغه أدعو عليهم، وعندما تهدأ نفسي أستغفر الله، وأحاول أن أسامحهم، ولكنني أعود، وأدعو عليهم عندما أفكر بما سببوه لي من آلام، هل لكم من توجيه سماحة الشيخ؟","title":"حكم الدعاء على الظالم","answer":"الجواب: لا حرج في الدعاء على من ظلم بقدر ظلمه، قال الله تعالى: لا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148] فمن ظلم استحق أن يدعى عليه، وإذا سمحت وعفوت فلك أجر عظيم، وإذا دعوت على من ظلمك بقدر ظلمه، وأن الله يجازيه عن ظلمه بما يستحق فلا حرج، وإذا تركت، وعفوت فالأجر أكبر، ولك أجر عظيم إذا عفوت، وصبرت، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15839/حكم-الدعاء-على-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58725.mp3","categories":["مسائل فقهية متفرقة","الآداب والأخلاق المحمودة"]},{"id":17285,"question":"هذا مستمع من جدة يقول: سماحة الشيخ كنت أعمل مع جدي في متجر له لمساعدته، وكان عمري لا يتعدى ثلاث عشر سنة، وكان إذا خرج من المتجر أخذت بعض النقود بدون علمه، فهل أعيدها له الآن، علمًا بأنني محرج من إعادتها؛ لأنني أستحي أن أقول له: إنني كنت آخذ بهذه الطريقة، وهذا جهل مني؛ لكوني كنت صغيرًا في ذلك الوقت؟ ماذا علي سماحة الشيخ؟","title":"وجوب إرجاع حقوق الناس المسلوبة مع التوبة","answer":"الجواب: عليك أن تعيدها بالطريقة المناسبة، تعيدها وهو لا يعلم في أمواله، أو تقول: هذا جاءك بها إنسان يقول: إن لك حقًا عليه فجاء بها، ولا تقل: إنها من عندي أنا؛ وتبرأ إن شاء الله، تعيدها في ماله، سواءً بعلمه، وبغير علمه، ولا تضيفها إليك، لا تقل: أنا أخذتها، قل: أتى بها إنسان، يقول: إن لك عنده دراهم، وأتى بها. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16125/وجوب-ارجاع-حقوق-الناس-المسلوبة-مع-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59304.mp3","categories":["مسائل فقهية متفرقة"]},{"id":17355,"question":"من جمهورية مصر العربية المستمع (م. ن. أ) رسالة وضمنها قضية يقول فيها: أثناء عملي مندوبًا في إحدى الشركات لتوزيع منتجاتها حدث أنني أخطأت ذات يوم مع أحد العملاء للشركة، وأخذت منه ثمن وحدتين من هذه البضاعة زيادة على حساب البضاعة التي أعطيتها له في هذا اليوم، ولم أعرف بذلك، وأثناء توريد الإيراد للشركة وجدت أن معي ثمن وحدتين زيادة عن المطلوب للشركة، وعندما رجعت إلى هذا العميل كالعادة لأعطيه بضاعته قال لي: إنني في المرة الماضية أعطيته البضاعة ناقصة وحدتين، وقلت له: إنني سأعطيك وحدتين ولكن في يوم آخر، وحتى الآن لم أعطه إياها حيث أنني استقلت من الشركة بعدها مباشرة، فماذا أفعل الآن، وأنا أرغب في أن أعطيه نقودًا ثمن تلك الوحدتين إلا أنني لا أعرف مكانه بالضبط، فماذا أفعل؟ جزاكم الله خيرًا.","title":"ما يفعل من أخذ مالًا بالخطأ ولا يعرف مكان صاحبه","answer":"الجواب: عليك أن تتصدق بذلك على الفقراء بالنية عنه، ويكفي، ومتى عرفته بعد حين، وطلبها تخيره، إن شاء قبل الصدقة وصار الأجر له، وإن شاء أعطيته وصار الأجر لك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16234/ما-يفعل-من-اخذ-مالا-بالخطا-ولا-يعرف-مكان-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83411.mp3","categories":["مسائل فقهية متفرقة","فتاوى متنوعة"]},{"id":17566,"question":"يقول: يوجد في بعض المناطق ظاهرة في نهاية كل سنة، حيث يجمع مبلغٌ من أهل القرية، ثم يشترى به الأرز، واللحم، ثم يطبخ، ويأكل، وهم يعتقدون إذا لم يفعلوا ذلك؛ أنه سوف يصيبهم كوارث، وقحط، ومحن، ويقولون: نفعل ذلك دفعاً للبلاء، هل ذلك جائزٌ في الإسلام؟ مع التعقيب عليه، جزاكم الله خيرًا.","title":"حكم الاجتماع على الطبخ والأكل بنية دفع البلاء","answer":"الجواب: هذا العمل على هذا الوجه، لا أعلم له دليلًا، كونهم يجمعون ويشترون طعام، يطبخون، ويأكلون، هذا لا أعلم له وجه، وإنما السنة أن يتصدق على الفقراء، لاشك أن الصدقة على الفقراء مما يدفع الله به البلاء، تحصل به الرحمة، كونهم يجمعون الفلوس، أو كل واحدٍ يتصدق، أو يمشي عليهم بعض الناس قد يطلب منه الصدقة، ويوزعها على الفقراء، أو يصنعون بها طعامًا، ويوزع على الفقراء، كل هذا طيب، ينفع الله به؛ لأن الصدقة تدفع البلاء، الصدقة من أسباب دفع البلاء، من أسباب رحمة الله لعباده، ارحموا؛ ترحموا، الراحمون يرحمهم الرحمن، من لا يرحم؛ لا يرحم، كما قاله النبي عليه الصلاة والسلام. والصدقات، والإحسان للفقراء والمساكين، هذا من أفضل العبادات، ومن أفضل أسباب دفع البلاء، وحصول الغيث والرحمة من الله، لكن كونه يجمع، ويأكلون في المطبخ ويأكلون هم، لا أعلم له أصلًا، إنما يجمع للصدقة للفقراء، أو كل واحدٍ يتصدقون، أو كل إنسان مما أعطاه الله يتصدق على الفقراء، أو يجمعونه ويوزعونه على الفقراء، أو يطبخونه ويوزعونه على الفقراء، رحمة لهم، وإحسانًا إليهم. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16482/حكم-الاجتماع-على-الطبخ-والاكل-بنية-دفع-البلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72603.mp3","categories":["مسائل فقهية متفرقة"]},{"id":17700,"question":"هذا السائل أبو عبد الله يقول: إذا كان في نفسي شراء حاجة ليست ضرورية ولكنها من الكماليات وأنا عندي وفرة مالية هل هذا يعد من الإسراف؟","title":"حكم شراء الكماليات","answer":"الجواب: ليس من الإسراف إذا كانت كماليات تزود فراش ليس بإسراف، تزود إناء يحتاجون إليه، تزود يعني: إدام يكفي الجميع ليس بإسراف، الإسراف الذي يأتي بشيء لا حاجة إليه هذا الإسراف. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16645/حكم-شراء-الكماليات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77606.mp3","categories":["مسائل فقهية متفرقة"]},{"id":17755,"question":"السائلة (س. س. س) تقول: نسكن في بلدة ليس بها كهرباء ولكن تقول: أنا وزوجي نسكن في بيت يسكن فيه عمال لمستوصف حكومي الكهرب يشتغل فيه بالليل والنهار، وقد أخذنا من هذا المستوصف سلك ووصلناه لمنزلنا وهذا ليس بعلم شركة الكهرباء المسئولة عن مواطير المستوصف، هل هذا حرام؟","title":"حكم أخذ الكهرباء بغير إذن الشركة المسؤولة","answer":"الجواب: نعم. لا يجوز هذا أخذ بغير حق، لا بد أن تراجع الجهة المسئولة عن ذلك حتى تسمح، الله حرم على العباد دماءهم، وأموالهم، وأعراضهم، وهذا داخل في الأموال، خطب النبي ﷺ الناس في حجة الوداع وقال في يوم عرفة، وفي يوم النحر على رءوس الأشهاد يخاطب الناس: إن الله حرم عليكم، دماءكم، وأموالكم، وأعراضكم، إن دماءكم، وأموالكم، وأعراضكم؛ عليكم حرام كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا هكذا قال النبي ﷺ للناس على رءوس الأشهاد يوم عرفة ويوم النحر، وقال عليه الصلاة والسلام: كل المسلم على المسلم حرام دمه، وماله، وعرضه فليس لأحد أن يأخذ من مال غيره بغير حق لا شركة، ولا حكومة ولا غير ذلك.\nالمقدم: جزاك الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16727/حكم-اخذ-الكهرباء-بغير-اذن-الشركة-المسوولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77711.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18076,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من البحرين، باعثتها إحدى الأخوات المستمعات من هناك، الواقع رسالتها مطولة سماحة الشيخ، لكن ملخص ما في هذه الرسالة: أن أمها تطلقت من أبيها، وحينئذٍ تزوجت أمها برجلٍ آخر، من بلدٍ آخر، فنسبت الأم البنت إلى الزوج الجديد، وأصبحت تستحق بتلك النسبة حقوقًا معينة، كما يستحقها مواطنو ذلك البلد، ثم إنها أخبرت والدها بالموضوع، لكنه تساهل في حياته، وقال: هذه ابنتي، ومصيرها تعود إلي، ثم توفى الله أباها، وحينئذٍ بدأت تفكر في تصحيح وضعها؛ إذ لو بقيت على تلك النسبة المزعومة؛ لاستحقت أموالًا وحقوقًا معينة، ولو أهملتها لفرطت في أشياء كثيرة، وترجو من سماحتكم التوجيه؟ جزاكم الله خيرًا.","title":"حكم من نسب إلى غير أبيه من غير إرادته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذا العمل أمر منكر، ولا يجوز أن ينسب الإنسان إلى غير أبيه، سواءٌ كان رجلًا، أو امرأة، وهذا العمل الذي فعلته المرأة وزوجها الجديد، أمرٌ منكر، والواجب عليهما التوبة إلى الله من ذلك، وتصحيح الوضع، بأن تنسب إلى أبيها، ويزال ما هناك من أوراق تنسبها إلى الزوج الجديد، هذا هو الواجب على الجميع، وليس لها حق في هذا العمل، بل هو منكر، والرسول ﷺ حذر من نسبة الإنسان إلى غير أبيه، وتوعد على ذلك، وأخبر أن هذا من أنواع الكفر، يعني: الكفر الأصغر. فالمقصود؛ أنه محرم، ولا يجوز انتساب الإنسان إلى غير أبيه، ولا أن ينسب إلى غير أبيه، فالواجب على المرأة، وعلى زوجها الجديد، وعلى زوج البنت، وعلى أم أبي البنت التصحيح، تصحيح الوضع من جميع الوجوه، وإن كان فيها نزاع، أحد ينازع في هذا الشيء، فليرد إلى المحكمة، أما إذا كان ما هناك نزاع؛ فالواجب على الجميع تصحيح الوضع، وأن يزال ما في أيديها من الوثائق التي تنسبها إلى غير أبيها، وأن تعطى وثيقة بالنسبة إلى أبيها الصحيح، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، تذكر سماحة الشيخ؛ أنها في رسالتها إذا صححت وضعها، ونسبت نفسها إلى أبيها الحقيقي، أنها ستخسر أشياء وأشياء، ولاسيما أنها في وظيفةٍ مرموقة، كما تقول، ما هو توجيه سماحتكم؟ الشيخ: ولو خسرت، ما يجوز لها أن تأخذ بالكذب شيئًا، يجب عليها أن تترك الكذب، ولو خسرت ملايين، ما يجوز لها أن تبقى على هذا الحالة أبدًا، نسأل الله العافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا نصيحة سماحتكم لهذه المستمعة: أن تصحح وضعها، ولو خسرت مهما خسرت. الشيخ: نعم، نعم، ولو خسرت الوظيفة، وغير الوظيفة. نعم. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17112/حكم-من-نسب-الى-غير-ابيه-من-غير-ارادته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73001.mp3","categories":["مسائل متفرقة في العقيدة","مسائل فقهية متفرقة"]},{"id":18081,"question":"المستمع: علي محمد إبراهيم من ليبيا، بعث بثلاثة أسئلة، في أحد أسئلته يقول: البعض من أهل السنة يخلع سنه الرباعية اقتداءً بالرسول ﷺ ما قولكم فيمن يفعل ذلك؟","title":"حكم ادعاء أن خلع السن الرباعية سنة","answer":"الجواب: هذا لا أصل له، هذا غلط، الرسول ﷺ ما خلعها، كسرت في يوم أحد كسرًا، ليس باختياره، الإنسان لا يخلع سنه بغير سبب، أما إذا كان بسبب، يعني: آلمه، فخلعه لأجل الألم؛ لا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17116/حكم-ادعاء-ان-خلع-السن-الرباعية-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73005.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18116,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ المستمع عنان بن عرار بن حسن العزمي من الخرج، أخونا له سؤالان كتبهما بلهجته العامية، مفهوم السؤال الأول: أنه اشتغل عنده بعض اليمنيين، ثم سافر ذلكم اليماني وله ألف ريال عند الأخ عنان ، ويسأل كيف يتصرف إذ لم يعد صاحب الحق حتى الآن؟","title":"كيفية التصرف بمالٍ تركه صاحبه ولم يرجع إليه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان صاحب الحق غير معروف فإنك تتصدق به عنه، تعطيه بعض الفقراء بالنية عن صاحبه، أما إذا كان معروفًا لديك في إمكانك أن ترسل المبلغ إليه على عنوانه فإنك ترسله إليه، أو كنت تظن أن يرجع إليك فاصبر ولا تعجل حتى يرجع إليك، فإن تصدقت به ثم جاء فهو مخير إن شاء أمضى الصدقة وصار الأجر له، وإن شاء طالب بحقه تعطيه حقه ويكون الأجر لك فيما تصدقت به، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا، يقول: إن هذا غائب منذ ثمان سنوات سماحة الشيخ؟ الشيخ: مادام هكذا فإنه يشرع لك أن تتصدق به؛ لأن الغالب أنه لا يأتي، ومادمت لا تعرف محله ولا عنوانه تتصدق بالمبلغ للفقراء أو في بعض المشاريع الخيرية بالنية عن صاحبه والله يعطيه أجره سبحانه وتعالى. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17146/كيفية-التصرف-بمال-تركه-صاحبه-ولم-يرجع-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90501.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18413,"question":"السائل (ص. س) من أبها والذي استعرضنا سؤالًا له بقي له هذا السؤال يقول: قام أحد الأصدقاء بإرسال أحد العمال في العمل بأن يأتي له بغداء، وأعطاه ثمن ذلك الغداء وكان سبعة ريال، فلما أحضر العامل الغداء وجده أكثر مما طلب، أي: أن ثمنه ستة عشر ريالًا، فقام بالأكل دون أن يتصرف في ذلك على أنه صاحب المطعم هو الذي أخطأ، فهل يعطي صاحب المطعم الفرق في الزيادة؟ أم ماذا يفعل هذا الرجل؟","title":"حكم أخذ شيء زائد عن المطلوب بسبب خطأ العامل","answer":"الجواب: هذا فيه تفصيل، إن كان العامل تبرع بالزيادة لصاحبه فهذا على العامل، ولا بأس إذا تبرع بالزيادة، أما إن كان أخطأ قد غلط صاحب المطعم فأعطاه ما هو بستة عشر وهو غلطان فالواجب أن يعطى الزيادة التي غلط فيها، الواجب على الآكل أن يعطيه الزيادة، فإذا كان فيه طعام بسبعة أو ثمانية، والطعام بستة عشر، وأعطاه الطعام المعروف أنه بستة عشر؛ فعليه يكمل يعطيه عما زاد؛ لأن غلطه لا يحل له طعامه، أما إذا كان متبرعًا .. صاحب المطعم، أو العامل متبرع؛ فلا بأس. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17487/حكم-اخذ-شيء-زاىد-عن-المطلوب-بسبب-خطا-العامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78416.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18443,"question":"من اليمن - صنعاء هذه رسالة بعث بها أحد الإخوة من هناك يقول: محمد فتح الله سالم السميم -فيما يبدو- مدرس مواد إسلامية وعربية بالمعاهد العلمية في صنعاء، أخونا يسأل ويقول في بداية رسالته:بسم الله الرحمن الرحيم، إلى فضيلة الشيخ عبد العزيز بن باز الرئيس العام للجنة الإفتاء والدعوة والإرشاد بالمملكة العربية السعودية، السلام عليكم ورحمة الله وبركاته، وحفظكم الله تعالى ووفقكم لأداء رسالة الإسلام والمسلمين، فضيلة الشيخ! قرأت في باب ما جاء في الأسماء والكنى صفحة (626 ، 627) من كتاب فتح الغفار المشتمل على أحكام سنة نبينا المختار ﷺ للقاضي العلامة شرف الدين الحسن بن أحمد الرباعي اليمني رحمه الله تعالى مجموعة من الأحاديث في هذا الباب المذكور لا أدري هل النهي بها مما يجب العمل به أم أن أحاديث أخرى تعارض ذلك، فتبيح التسمية باسمه ﷺ والكنية بكنيته؟ وهل من سمى ولدًا له قاسمًا أو القاسم يجوز له عند ندائه باسم ولده يا أبا القاسم أو يا أبا قاسم ولتوضيح ذلك فهذه هي الأحاديث الواردة في هذا الشأن، عن أبي هريرة : أن النبي ﷺ قال: لا تسموا باسمي ولا تكنوا بكنيتي، أخرجاه.وعن علي  قال: «يا رسول الله! أرأيت إن ولد لي بعدك ولد اسميه محمدًا، وأكنيه بكنيتك؟ قال: نعم، فكانت رخصة لي» رواه الترمذي وقال: حديث حسن صحيح.وعن عائشة رضي الله عنها قالت: «جاءت امرأة إلى النبي ﷺ فقالت: يا رسول الله! إني ولدت غلامًا فسميته محمدًا وكنيته أبا القاسم فذكر لي أنك تكره ذلك فقال: ما الذي أحل اسمي وحرم كنيتي، أو ما الذي حرم كنيتي وأحل اسمي رواه أبو داود وقال المنذري: غريب، نرجو من فضيلتكم إفادتنا عن ذلك؟ جزاكم الله خير الجزاء.","title":"حكم التسمي باسم النبي ﷺ والتكني بكنيته","answer":"الجواب: الصواب في هذا الثابت عن النبي ﷺ أنه قال: تسموا باسمي ولا تكتنوا بكنيتي وهذا عند العلماء في حياته ﷺ؛ لأنه إذا نودي أبا القاسم قد يشتبه على الناس، قد ربما التفت إذا كان يسمع عليه الصلاة والسلام يظن أنه هو المدعو والمدعو غيره. أما التسمي باسمه فلا حرج فيه في حياته وبعد وفاته عليه الصلاة والسلام، وقد سمى الصديق  في حياة النبي ﷺ ابنه محمدًا، في حجة الوداع سماه محمدًا، وكان في الصحابة محمد بن مسلمة ولم يغيره النبي عليه الصلاة والسلام، فالتسمي باسمه لا حرج فيه، وإنما نهى عن كنيته أبا القاسم ثم أذن فيها بعد وفاته ﷺ لـعلي والإذن لـعلي إذن للناس؛ لأن المحذور زال، لما توفي عليه الصلاة والسلام زال المشكل، وزال المحذور، فلا حرج في التسمية باسمه ولا حرج في التكني بكنيته بعد وفاته عليه الصلاة والسلام، أما اسمه فلا حرج فيه مطلقًا حتى في حياته ﷺ. أما الكنية فكانت منهيًا عنها في حياته ﷺ ثم بعد وفاته.. رخصة كما رخص فيها النبي ﷺ؛ ولأن العلة التي من أجلها نهي عن التكني بكنيته في حياته قد زالت بموته عليه الصلاة والسلام، وبهذا يعلم وأنه لا حرج والحمد لله، لا في التسمي باسمه، ولا في التكني بكنيته عليه من ربه أفضل الصلاة والتسليم. المقدم: إذًا: هذا وجه الجمع بين ما يظهر من أن الأحاديث متعارضة؟ الجواب: نعم.. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17522/حكم-التسمي-باسم-النبي-ﷺ-والتكني-بكنيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_915/nour_91504.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18472,"question":"رسالة بعث بها أحد الإخوة المستمعين يقول المرسل عبد الرحمن، مواطن سعودي يعمل في دولة الإمارات العربية المتحدة، أخونا له مجموعة من القضايا:في قضيته الأولى يقول: عندما قمت ببناء منزلي وأنهيته، وقمت ببناء الارتداد -الحائط- على المنزل -أو ما نسميه بالحوش في مصطلحنا- كان البيت على شارعين، وبين الشارع الشرقي والشمالي كتب في الحجة - حجة الاستحكام - شطفة سبعة متر، وأثناء التحويط لم أتقيد بذلك، وجعلت الشطفة بدل سبعة متر ثلاثة متر تقريبًا نظرًا لضيق الحوش، فأصبح الضلع الشمالي خمسة عشر مترًا بدل اثنا عشر متر، والضلع الشرقي سبعة عشرًا بدل خمسة عشر مترًا كما هو الواضح في الصك.فهل يلزمني إعادته على طبيعته بهدمه وإعادة بنائه، علمًا أنه ليس هناك أذى على أحد، أم أتركه ليوسع الحوش ولكي لا يحتك بالبنيان المنزلي، أرجو توجيهي لما فيه الصلاح فضميري يؤنبني بالرغم أنني لم أوذ أحدًا، ولكن هناك مخالفة للبلدية، واعلموا أن البلدية عندما صرفت لي آخر قسط لم تستنكر هذه الزيادة وصرفوا لي المبلغ المتبقي، أرجو إفادتي حفظكم الله؟","title":"حكم أخذ زيادة من الأرض على ما في الصك","answer":"الجواب: عليك أن تراجع الجهة المسئولة وهي البلدية، وتتفاهم معها في الموضوع، فإذا سمحت لك بذلك فالحمد لله، وإلا فعليك أن تلتزم بما وضعته الدولة لمصالح المسلمين، والله المسئول أن يوفق الجميع. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17557/حكم-اخذ-زيادة-من-الارض-على-ما-في-الصك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86602.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18557,"question":"رسالة وصلت إلى البرنامج من المدينة المنورة، وباعثها أحد الإخوة يقول: (أ. د) أخونا يسأل عن العملة الورقية التي تكتب عليها كلمة التوحيد، كيف نتصرف تجاهها؟جزاكم الله خيرًا.","title":"كيفية التعامل مع النقود التي تحتوي على كلمة التوحيد","answer":"الجواب: تحفظها معك في جيبك، ولا حرج عليك إذا دخلت بها الحمام أو غير الحمام؛ لأنك مضطر إلى ذلك، والحكم في هذا عند بعض العلم كراهة الدخول بشيء فيه ذكر الله للحمام، ولكن إذا احتاج الإنسان لذلك، أو خاف على نقوده، أو نسيها في جيبه، أو خاف عليها فلا كراهة؛ لأن إخراج النقود، ووضعها خارج الحمام قد تسرق، أو قد ينساها، أو قد يأخذها بعض الأطفال، فالمقصود: أنه لا حرج إذا دعت الحاجة إلى ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17667/كيفية-التعامل-مع-النقود-التي-تحتوي-على-كلمة-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91608.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18587,"question":"تقول السائلة أيضًا من الشارقة من أسئلتها يا سماحة الشيخ: هل يتيم الأم يعتبر يتيمًا ويدخل تحت كفالة اليتيم؟ وما هو السن القانوني الذي ينتهي عنده اليتم؟","title":"التعريف باليتيم والسن الذي تزول به صفة اليتم","answer":"الجواب: اليتيم: هو الذي مات أبوه لا أمه، الذي ماتت أمه ما يسمى يتيمًا، اليتيم: الذي مات أبوه وهو صغير قبل أن يبلغ، فإذا بلغ الحلم زال عنه اسم اليتم، إذا كمل خمسة عشر سنة، أو أنزل المني عن شهوة، أو أنبت الشعر الخشن حول الفرج صار رجلًا، ولم يكن يتيمًا، والمرأة كذلك إذا حاضت أو بلغت خمسة عشر سنة، أو أنبتت الشعرة التي حول الفرج أو أنزلت المني عن شهوة في الليل أو في النهار بالاحتلام صارت امرأة.","link":"https://binbaz.org.sa/fatwas/17695/التعريف-باليتيم-والسن-الذي-تزول-به-صفة-اليتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91809.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18653,"question":"أخونا يسأل أسئلة أخرى فيقول مثلًا: ما حكم الشرع في الممثلين والمشاهدين؟ وما يدفع ويؤخذ من مال لأجل ذلك؟","title":"حكم الشرع في التمثيل","answer":"الجواب: هذا سؤال مجمل، وكأنه يقصد في الزواج، فالممثل والمشاهد، المشاهد إذا كانت الأشياء التي يشاهدها ليس فيها محذور، امرأة تشاهد النساء عند اجتماعهن، وعند ضربهن الدف، وغنائهن الغناء المعتاد بين النساء لا حرج في ذلك. أما الممثل ففيه تفصيل: إن كان المقصود بالممثل أنه الذي يتزيا بزي غير زيه، وينسب نفسه إلى غيره، كأن يتزيا بزي النساء، يتشبه بالنساء على أنه فلانة أو فلانة هذا منكر من جهتين: من جهة كذبه، ومن جهة تزييه بزي النساء، والله حرّم على الرجل أن يلبس لبس المرأة. وإن كان التمثيل بشخص آخر يتقمص ويقول: أنا فلان، والثاني يقول: أنا زوج المرأة فلانة، أو أنا أبوها، أو أنا أخوها، وليس كذلك، أو أنا عمر، أو أنا علي بن أبي طالب، أو أنا أحمد بن حنبل، أو أنا أبو حنيفة، أو أنا فلان، فهذا كذب لا يجوز، وهذا تزوير، وليس تمثيل، تزوير؛ لأنه ليس بـأبي حنيفة، وليس بـأحمد، وليس عليًا، وليس نحو ذلك. وإذا كان يتشبه بالكفرة صار أكبر وأشد، كأن يقول: أنا أبو جهل، أو أنا عتبة بن ربيعة، أو أنا أبو لهب، هذا أقبح؛ لأنه مثل نفسه بالكافر، وكذب أيضًا ليس هو بـأبي لهب، وليس هو بـعتبة، وليس هو بـأبي جهل، فلا يجوز.  وبعض الناس لا يفهم التمثيل، يحسب أن التمثيل ضرب الأمثال، فضرب الأمثال لا، نوع آخر، ضرب الأمثال ضرب الله لنا ذلك في كتابه العظيم في أشياء كثيرة، مثل قوله -جل وعلا-: وَاضْرِبْ لَهُمْ مَثَلًا رَجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَابٍ وَحَفَفْنَاهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا [الكهف:32].. وَضَرَبَ اللَّهُ مَثَلًا قَرْيَةً كَانَتْ آمِنَةً مُطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِنْ كُلِّ مَكَانٍ [النحل:112] إلى أمثال هذا من الأمثلة> فالأمثلة التي يضربها الله أو يضربها رسوله ﷺ هذه فيها البيان والإيضاح للأمة؛ حتى تعرف الحق بالأدلة وبالتمثيل، وهكذا لو قال إنسان لجماعة يضرب لهم الأمثال: مثل الذي يفعل كذا، مثل كذا وكذا، والذي يفعل كذا مثله كذا؛ للتنفير من الأفعال السيئة، أو للترغيب في الأعمال الطيبة، هذا لا بأس به، هذا ضرب الأمثال للإيضاح والبيان، بخلاف التمثيل الذي هو تقمص إنسان، يقول: أنا فلان، أو أنا فلانة، وهو كذب ليس بفلان ولا فلانة، هذا كذب وتزوير لا يجوز، وإذا كان ذلك في أشخاص كفار كان أقبح وأشد إثمًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17782/حكم-الشرع-في-التمثيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_872/nour_87204.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18672,"question":"يسأل أخونا أيضًا سؤالًا آخر ويقول: يوجد لدينا أشخاص كثيرون يقفون في الطرقات، ويمدون أيديهم التماسًا للحصول على النقود، ولا ندري أهؤلاء الأشخاص يصلون ويستحقون الصدقة أم لا؟!وكذلك لا ندري هل هم بحاجة إليها أم لا؟! ومع هذا فإننا نتحرج إذا لم نعطهم، تطبيقًا لقوله تعالى: وَأَمَّا السَّائِلَ فَلا تَنْهَرْ [الضحى:10] فهل إعطاؤهم جائز ومطلوب منا؟ أم هو من قبيل معاونتهم على البطالة والتكاسل عن العمل؟وإذا كنا لا نعرف حالهم هل مقيمون لحدود الله أم لا، فما الحكم فيما نقوم به؟ أفيدونا، وفقكم الله.","title":"كيفية التعامل مع المتسولين","answer":"الجواب: يقول الله سبحانه: وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19] في أموال المؤمنين حق للسائل والمحروم، والسائل له أحوال ثلاثة: تارة تعلم أنه غني، وتارة تعلم أنه فقير، وتارة لا تعلم حاله. فإذا كنت لا تعلم حاله، أو تعلم أنه فقير، فالسنة لك أن تعطيه ما تيسر، ولو قليلًا: فاتقوا النار ولو بشق تمرة. أما إن كنت تعلم أنه غني فالواجب نصيحته، ونهيه عن هذا العمل، وزجره عن ذلك؛ لأن الله حرمه عليه، لا يجوز السؤال وهو في غنى، يقول النبي ﷺ: من سأل الناس أموالهم تكثرًا، فإنما يسأل جمرًا، فليستقل أو ليستكثر. فالواجب على من كان عنده مال يكفيه أن لا يسأل، وأن يحذر السؤال، أما أنت أيها المار بالسائل! إذا كنت لا تعرف حاله، أو تعرف أنه فقير فيستحب لك أن تعطيه ما تيسر، للآية الكريمة: وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19] وفي الآية الأخرىوَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَعْلُومٌ ۝ لِلسَّائِلِ وَالْمَحْرُومِ [المعارج:24-25]. وليس لك أن تنهره؛ لقول الله سبحانه: وَأَمَّا السَّائِلَ فَلا تَنْهَرْ [الضحى:10] وقوله -جل وعلا-: قَوْلٌ مَعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِنْ صَدَقَةٍ يَتْبَعُهَا أَذًى [البقرة:263]. وإذا كان شابًا تنصحه أن يعمل إذا وجد عملاً حتى يستغني عن السؤال، إذا كان قويًا حتى ولو كان غير شاب، فإذا كان قويًا تنصحه أن يعمل ويكدح يطلب الرزق، حتى يغنيه الله عن السؤال، فالمؤمن ينصح أخاه ويوجهه إلى الخير، ويعينه على الخير، ويساعده إذا احتاج إلى مساعدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17789/كيفية-التعامل-مع-المتسولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92004.mp3","categories":["مسائل فقهية متفرقة"]},{"id":18979,"question":"أيضًا تستنصح سماحتكم فيما يخص الفيديو، وما يتبع الفيديو.","title":"حكم اقتناء الفيديو","answer":"الجواب: هذه الفيديو والتلفاز فيها أخطار، فإذا كان الإنسان لا ينظر ولا يشاهد إلا ما ينفعه فلا حرج عليه، أما مشاهدة الأفلام الخليعة، والمسلسلات الخليعة، أو سماع الأغاني والملاهي، فهذا منكر، لا يجوز، لا من التلفاز، ولا من الفيلم، ولا من الإذاعة، ولا من غير ذلك.  فالواجب على المؤمن والمؤمنة التحفظ من هذه الأمور، والحرص على سلامة القلب واللسان، وسلامة الأذن من استماع ما حرم الله ، فالمؤمن يتحرى أن يستمع، وأن يشاهد ما ينفعه في دينه ودنياه، وأن يبتعد عما يضره في دينه ودنياه، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/18097/حكم-اقتناء-الفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92409.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19039,"question":"يقول السائل من القصيم يا سماحة الشيخ: هل يجب أن نحترم وجهة نظر الغير في الأمور المباحة، مثل أن فلان صوت قراءته أفضل من الآخر، خاصةً وأن الناس لا يقتنعون برأي الآخرين إلا عند المشورة وليس في النقاش؟","title":"حكم تفضيل شخص على شخص في أمر ما","answer":"الجواب: لا بأس على سبيل النصيحة فلان أحسن صوتًا، أو أحسن ترتيلًا من باب النصيحة لمن يريد أن يستمع ويستفيد لابأس بهذا لا على وجه الغيبة أو الإنكار، ولكن على سبيل البيان أن فلان أحسن قراءة من فلان أو أحسن ترتيلًا من فلان حتى يستفيد منه من يريد سماع قراءته. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18216/حكم-تفضيل-شخص-على-شخص-في-امر-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88311.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19254,"question":"يسأل فيقول: هل يجوز ذبح شاة أو دجاجة في البيت الجديد قبل النزول فيه؟","title":"حكم الذبح عند دخول البيت الجديد","answer":"الجواب: إذا كان اعتقاد أنه يدفع الجن أو أشباه ذلك؛ هذا لا يجوز، أما إذا ذبح لأهله أو جمع الجيران شكرًا لله، وجعل لهم وليمة للجيران؛ فهذا لا بأس به طيب من باب الشكر لله جل وعلا، أما أن يذبح دجاجة أو ذبيحة أخرى عند تأسيسه أو عند انتهائه؛ خوفًا من الجن، أو اعتقاد أنه يدفع الجن أو أنه يحصل به كذا وكذا، هذا من البدع لا يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18447/حكم-الذبح-عند-دخول-البيت-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73817.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19291,"question":"أخونا يقول: تكثر عندنا المناداة بكلمة: سيد فلان، وذلك لكونه يرجع في النسب إلى أسر معينة، هل يصح هذا؟","title":"حكم مناداة الشخص بلفظ: السيد فلان","answer":"الجواب: إذا عرف بذلك فلا بأس، السيد فلان السيد فلان؛ لأن كلمة السيد تطلق على رئيس القوم، وعلى الفقيه والعالم، وعلى من كان من ذرية فاطمة من أولاد الحسن والحسين يقال له: سيد، كل هذا اصطلاح بين الناس معروف، وكانت العرب تسمي رؤساء القبائل والكبراء سادة، سيد بني فلان فلان، وسيد بني فلان فلان، ومثلما قال النبي ﷺ لما سأل بعض العرب: من سيدكم يا بني فلان؟! من سيدكم يا بني فلان؟ يعني: من رئيسكم، ومثلما قال ﷺ في الحسن: إن ابني هذا سيد ولعل الله يصلح به بين فئتين عظيمتين. إنما يكره أن يخاطب الإنسان بسيدي، يا سيدي، يا سيدنا يكره هذا؛ لأن الرسول ﷺ لما قيل له: أنت سيدنا، قال: السيد الله تبارك وتعالى، ولأن هذا قد يكسبه غرورًا، وتكبرًا، وتعاظمًا فينبغي ترك ذلك، بل يقال: يا أبا فلان! يا فلان! يا أبا فلان! بالأسماء والألقاب التي تعرف، وأما التعبير عند المخاطبة له يا سيدي، يا سيدنا، ترك هذا هو الأولى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18482/حكم-مناداة-الشخص-بلفظ-السيد-فلان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94103.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19309,"question":"ما حكم قطع الثمار أو الأشجار التي تكون للعامة وليست لأحد معين؟","title":"حكم قطع الأشجار العامة","answer":"الجواب: الأشجار التي في البراري والقفار غير مملوكة لأحد، هذا ينظر فيها، فإن كان فيها مصلحة للمسلمين يستظلون بها، ترعاها دوابهم لا تقطع، أما إن كانت في مضرة في طريق يؤذي المسلمين.. في محل يؤذي المسلمين فقطعها فيه أجر، وقد ثبت عن رسول الله عليه الصلاة والسلام: أن رجلًا رأى غصن شوك في طريق المسلمين -وفي رواية: شجرة في طريق المسلمين- فقطعها، وقال: أزيلها عن أذى المسلمين، فشكر الله له ذلك، وغفر له. فالحاصل أن هذا فيه تفصيل: فالذي ينفع الناس بقاؤه لا يقطع، والذي يضر الناس بقاؤه يزال، والمملوك لا يزال إلا بإذن ربه، إذا كان مملوك لا يزال إلا بإذن صاحبه، وإذا كان يؤذي الناس يرجع فيه إلى المحكمة، ولا يتجرأ الناس على ملك الناس إلا من طريق الشرع. أما في البراري والصحراء التي ليس فيها ملك لأحد بل للمسلمين عامة، فهذا مثل ما تقدم، يرعى المسلم فيها، يرعي إبله وغنمه وبقره، يحتش منها لا بأس، لكن لا يقطع الشجر الذي ينفع الناس ويستظلون به، أو هو علامات على مياه أو على بلدان، يهتدي بها السالكون، هذا يترك، لا يتعرض له؛ لأن في قطعها مضرة، أما إذا كانت الشجرة أو الغصون في طرق تؤذي الناس، فإنها تزال، وصاحبها مشكور ومأجور.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18466/حكم-قطع-الاشجار-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89211.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19355,"question":"نعود في هذه الحلقة إلى رسالة المستمع مفتاح مصطفى من الجماهيرية، أخونا عرضنا جزءًا من أسئلته في حلقات مضت، وفي هذه الحلقة بقي له مجموعة من الأسئلة من بينها سؤال: عن السينما والمسرح وحكم الدخول إليها من المسلم، هل هو جائز أو لا؟","title":"حكم دخول السينما والمسرح","answer":"الجواب: هذا فيه تفصيل: إن كان المسرح والسينما فيها شيء ينفع المسلمين ويوافق الشريعة، كمسرح فيما يتعلق ببيان الحق ونشر الحق، وبيان ما درج عليه سلف الأمة ونحو ذلك، أو سينما لإيضاح الحق في مسائل تهم الناس، ليس فيه عري، ولا فساد، ولا اختلاط، ولا أغاني، ولا شبه ذلك من المنكرات هذا لا بأس، إذا كان خالٍ مما حرم الله  وإنما أقيم لمصلحة إسلامية، أو لمصلحة مباحة كإبانة صناعة نافعة أو أشياء مما تهم المسلمين وتنفعهم في دينهم أو دنياهم بلا محذور، من دون وجود اختلاط رجال بنساء ومن دون أغاني وملاهي من دون شيء محرم. أما السينمات المعروفة، والمسارح المعروفة التي فيها الاختلاط للرجال والنساء، أو فيها الأغاني والملاهي، أو فيها عري النساء، أو فيها ما غير ذلك مما حرم الله؛ فهذا منكر لا يجوز، لا يجوز دخولها ولا المجيء إليها ولا الرضا بها، بل يجب إنكارها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18552/حكم-دخول-السينما-والمسرح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89902.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19439,"question":"يقول أخونا في سؤال آخر: يوجد لدينا مورد للرزق يدر علينا بعض المال، ولكن أنا آخذ من هذا المال أكثر من إخوتي ولكن للحاجة الملحة، فهل علي إثم في ذلك؟الشيخ: أعد.المقدم: يقول: يوجد لدينا مورد للرزق يدر علينا بعض المال، ولكن أنا آخذ من هذا المال أكثر من إخوتي، ولكن للحاجة الملحة، فهل علي إثم بذلك؟ وإخوته كما ذكر في السؤال الأول ستة شيخ عبد العزيز .","title":"حكم من يأخذ من مال له ولإخوته زيادة عليهم","answer":"الجواب: إذا سمح لك إخوتك وهم مرشدون وقالوا لك: لا بأس أن تأخذ حاجتك مطلقًا فلا بأس، وإن لم يسمحوا فلابد من أن تأخذ حقك فقط لا زيادة، إذا كان بينكم على السواء، فإنك تأخذ نصيبك من دون زيادة، إلا بإذنهم إذا رضوا فلا بأس، أو رضي بعضهم جاز لك أن تأخذ من حق الراضي ما رضي به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18674/حكم-من-ياخذ-من-مال-له-ولاخوته-زيادة-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93803.mp3","categories":["مسائل فقهية متفرقة"]},{"id":19509,"question":"يقول السائل: يا سماحة الشيخ! التبسط والتنعم فيما أحل الله، هل هو منهي عنه؟","title":"حكم التبسط والتنعم فيما أحل الله","answer":"الجواب: لا بأس به، الحمد لله من غير إسراف.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18758/حكم-التبسط-والتنعم-فيما-احل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94608.mp3","categories":["مسائل فقهية متفرقة"]}]
